const PI: f32 = 3.14159265;

fn lobby_world(frag: vec4<f32>) -> vec3<f32> {
    let ndc = vec4<f32>(frag.x * LF.viewport.z * 2.0 - 1.0, 1.0 - frag.y * LF.viewport.w * 2.0, frag.z, 1.0);
    let h = LF.inv_vp * ndc;
    return h.xyz / h.w;
}
fn sh_irradiance(n: vec3<f32>) -> vec3<f32> {
