    let nl = max(dot(n, L), 0.0);
    let h = normalize(L + v);
    let nh = max(dot(n, h), 0.0);
    let vh = max(dot(v, h), 0.0);
    let f = f0 + (vec3<f32>(1.0) - f0) * pow(1.0 - vh, 5.0);
    let spec = ggx(nh, rough) * 0.25 * f;
