            let unoccluded = len * 3.14159265 * sky_refl.params.y;
            let between = acos(clamp(dot(bn.xyz, r) / max(len, 0.001), -1.0, 1.0));
            iso = cone_cone_intersection(refl_cone, unoccluded, between);
