    horizon: vec4<f32>,     // "Sky - Horizon color"
    zenith: vec4<f32>,      // "Sky - Zenith Color"
    params: vec4<f32>,      // x Star Brightness, y Horiz-X, z Horiz-Add, w Horiz-Pow
    tod: vec4<f32>,         // time-of-day weights (morning, day, evening, night)
    sun_c: vec4<f32>,       // billboard centre (metres, camera-relative)
    sun_r: vec4<f32>,       // billboard right axis
    sun_u: vec4<f32>,       // billboard up axis, w = metres per mesh cm
    center_world: vec4<f32>,
    cam_local: vec4<f32>,
    sun_model_world: vec4<f32>, // FortniteMaterialParameters.SunAndMoonModelWorldPosition (metres, GL world)
    fog: HeightFogU,        // TOD LIVE: the frame's height-fog view uniforms (common.wgsl)
}
// Unit camera forward (world) for the height-fog volumetric exclusion: `vp` is perspective_rh * view rotation, so clip.w = -z_view and
// the w row of `vp` is the view axis.
fn sky_forward() -> vec3<f32> { return normalize(vec3<f32>(sky.vp[0][3], sky.vp[1][3], sky.vp[2][3])); }

// M_AridClouds dome (SkyDomeMeshComp: FortniteSkyDome_Optimized scaled (2000,2000,167.7) cm, centred 1000 m below the TOD origin).
// Port of the pixel shader compiled into M_AridClouds (shader_17639: ps_5_0 of UE 4.16 / Fortnite 1.8, translucent base pass) with the
// M_AridClouds_Inst_Day constants (material cbuffer cb3[0..21] uploaded verbatim). Substitutions: View.RealTime -> time,
// View.ViewOrigin -> cam_world, FortniteMaterialParameters.SunAndMoonModelWorldPosition (MaterialCollection0[27]) -> sun_model_world, the dome's
// position -> center_world, UE world +Z (up) is this runtime's +Y, and the
// ExponentialHeightFog tail -> height_fog() (the volumetric-fog 3D texture lookup is done by the "vfog composite" pass, src/volfog.rs).
@group(0) @binding(0) var<uniform> sky: SkyU;
@group(0) @binding(1) var<uniform> cb3: array<vec4<f32>, 22>;
@group(0) @binding(2) var t_cloud: texture_2d<f32>;
@group(0) @binding(3) var samp: sampler;

struct VsOut {
    @builtin(position) clip: vec4<f32>,
    @location(0) uv0: vec2<f32>,
    @location(1) uv1y: f32,
    @location(2) tangent_x: vec3<f32>,
    @location(3) tangent_z: vec3<f32>,
    @location(4) world_pos: vec3<f32>,
}

// pos = dome-local metres (GL world); tc = (uv0.x, uv0.y, uv1.y, uv2.y); tz = tangent Z, tx = tangent X (unit, GL world).
@vertex
fn vs_main(@location(0) pos: vec3<f32>, @location(1) tc: vec4<f32>, @location(2) tz: vec3<f32>, @location(3) tx: vec3<f32>) -> VsOut {
    var o: VsOut;
    o.uv0 = tc.xy;
    o.uv1y = tc.z;
    o.tangent_x = tx;
    o.tangent_z = tz;
    o.world_pos = pos + sky.center_world.xyz;
    o.clip = sky.vp * vec4<f32>(pos - sky.cam_local.xyz, 1.0);
    o.clip.z = o.clip.w; // PERF: on the far plane (see sky_dome.wgsl): the depth test drops the covered pixels
    return o;
}

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    let time = sky.cam_world.w;
    let cam_world = sky.cam_world.xyz;
    let Tx = normalize(in.tangent_x);
    let Tz = normalize(in.tangent_z);
    let Ty = cross(Tz, Tx);                      // tangent sign assumed +1 (not recoverable without the mesh tangents)
    let V = normalize(cam_world - in.world_pos); // pixel -> camera
    // MATERIAL PARAMETERS (2026-10-06): `normalize(View.WorldCameraOrigin - MaterialCollection0[27])` (DXBC `add r3.xyz, cb1[59], -cb2[27]`): cb2 is the
    // program's MaterialCollection0 = FortniteMaterialParameters, float4 27 = SunAndMoonModelWorldPosition (sun model -> camera). It used to be read as the
    // dome's object position, which put the sun tint at the dome centre instead of around the sun.
    let from_sun = normalize(cam_world - sky.sun_model_world.xyz);
    var sunk = clamp((dot(V, from_sun) + cb3[16].x) * cb3[16].y, 0.0, 1.0);
    sunk = sunk * sunk; sunk = sunk * sunk;
    let sun_tint = sunk * cb3[2].xyz;
    let a = in.uv0 - 1.0;
    let scroll = time * cb3[16].w;               // BigCloudSpeed
    let uv_base = a * cb3[16].z + scroll;
    let swirl = a * cb3[17].x;                   // SwirlTile
    let r5 = time * vec2<f32>(0.013125, -0.02625) + swirl;
    let row = ceil(r5.x + 0.5);
    let p = vec2<f32>(r5.x, row * 0.5 + r5.y) + 0.5;
    let fr = fract(p) - 0.5;
    var d = max(1.0 - 2.0 * length(fr), 0.0);
    d = d * d * cb3[17].y;                       // RotAmtMod
    let ang = d * vec2<f32>(6.283185, -6.283185);
    let cell = ceil(p) - 0.5;
    var off = p - cell;
    let perp = vec2<f32>(-off.y, off.x) * sin(ang.x);
    off = off * cos(ang.x) + perp;
    let disp = (cell + off - p) * 0.09375;
    let uvA = uv_base * 0.125 + disp;
    let tA = textureSample(t_cloud, samp, uvA).xyz;
    let hA = tA.z;
    let uvB = uvA * cb3[17].w + time * cb3[17].z;
    let tB = textureSample(t_cloud, samp, uvB).xyz;
    let hh = (1.0 - hA) * ((tB.z - cb3[18].x) * cb3[18].y) + hA;
    let zen = (in.uv1y - cb3[18].w) * cb3[19].x;  // zenith -> horizon factor
    var thr = zen * (cb3[19].y - cb3[19].z) + cb3[19].z;
    thr = sunk * cb3[18].z + thr;
    let dens = hh - thr;
    let dsat = clamp(dens, 0.0, 1.0);
    let om = 1.0 - dsat;
    let lg = log2(max(om, 1e-6));                 // 1.8 compiled form: max(1 - dsat, 1e-6) before the log
    let p10 = exp2(lg * 10.0);
    let edge = om * 0.05 + p10;
    let nl = exp2(lg * cb3[19].w) * cb3[20].x;    // detail normal power / Normal Lerp
    let nxy = tA.xy + nl * (tB.xy - tA.xy);
    let n2 = (nxy - 0.5) * 2.0;
    let nz = sqrt(max(1.0 - dot(n2, n2), 0.0));
    let n6 = vec3<f32>(n2, nz);
    let a5 = vec3<f32>(n2, 0.0);
    let a7 = vec3<f32>(-n2.y, n2.x, 0.0) * sin(ang.y);
    var r5v = a5 * cos(ang.y) + a7 + vec3<f32>(0.0, 0.0, nz);
    r5v = (r5v - n6) * 0.5 + n6;
    r5v = normalize(r5v * cb3[4].xyz);            // Normal Modulator
    let N = Ty * r5v.y + Tx * r5v.x + Tz * r5v.z;
    var down = min(max(N.y, -1.0), 0.0);          // UE N.z (world up)
    down = down * down;
    var col2 = sun_tint * edge + (dsat * down) * cb3[6].xyz;   // Ground Cloud Color
    col2 = col2 + p10 * cb3[8].xyz * 0.1;         // Clouds - Direct Sun Light Color
    let edge_light = 2.0 * exp2(lg * cb3[20].y);  // Cloud Transparency Edge Lighting Falloff
    var L = clamp((0.75 - dot(from_sun, N)) * 0.571429, 0.0, 1.0); // DXBC `dp3 r0.x, r3.xyz, r0.xyz`: the same sun -> camera vector (r3) as the tint
    L = edge_light * L + L;
    let lit = L * cb3[8].xyz;
    let zc = clamp((in.uv1y - cb3[20].z) * cb3[20].w, 0.0, 1.0);
    let tint = cb3[12].xyz + zc * (cb3[11].xyz - cb3[12].xyz);
    var col = lit * tint + col2;
    col = mix(col, cb3[14].xyz, 1.0 - clamp(1.0 - in.uv1y, 0.0, 1.0));   // FogColor
    col = min(max(col, vec3<f32>(0.0)), vec3<f32>(1000.0)) + cb3[15].xyz;
    let opacity = clamp(zen, 0.0, 1.0) * (cb3[21].x - cb3[21].y) + cb3[21].y;
    let alpha = clamp(dens * opacity * cb3[21].z, 0.0, 1.0);
    let fog = height_fog(sky.fog, in.world_pos, cam_world, sky.to_sun.xyz, sky_forward());
    return vec4<f32>(col * fog.a + fog.rgb, alpha);
}
diagnostic(off, derivative_uniformity); 

// Shared WGSL helpers, prepended to every scene/sky shader by the Rust side (WGSL has no #include).
// Ported from FortniteRuntime/src/shaders/common.glsl + fog.glsl.
// All colour maths in the scene passes is linear; encoding to sRGB happens once, in post.wgsl.

fn decode_srgb(x: f32) -> f32 {
    if (x <= 0.04045) { return x / 12.92; }
    return pow((x + 0.055) / 1.055, 2.4);
}
fn encode_srgb(x: f32) -> f32 {
    if (x <= 0.0031308) { return x * 12.92; }
    return 1.055 * pow(x, 1.0 / 2.4) - 0.055;
}
fn to_linear(v: vec3<f32>) -> vec3<f32> { return vec3<f32>(decode_srgb(v.x), decode_srgb(v.y), decode_srgb(v.z)); }
fn to_srgb(v: vec3<f32>) -> vec3<f32> { return vec3<f32>(encode_srgb(v.x), encode_srgb(v.y), encode_srgb(v.z)); }
fn luma709(c: vec3<f32>) -> f32 { return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722)); }

// Unreal-style ExponentialHeightFog: the compiled TExponentialHeightFogPS<DirectionalLightInscatteringAndVolumetricFog> of the 1.8 global shader cache
// (ported in src/fog.rs `HeightFogPs::eval`, which this mirrors line for line), evaluated per fragment. World units here are metres (GL, Y up);
// the maths runs in Unreal units (cm, Z up = renderer Y).
// TOD LIVE: the values are PER-FRAME uniform data (src/fog.rs HeightFogUniform, the live clock's ExpHeightFogValues phase blend), not baked constants: the
// including shader passes its block (lit_common.wgsl `light.fog`, sky_common.wgsl `sky.fog`). Density / falloff carry the engine /1000 remap.
struct HeightFogU {
    p0: vec4<f32>,         // x FogDensity, y FogHeightFalloff (both /1000), z FogHeight (cm), w FogMaxOpacity
    p1: vec4<f32>,         // x StartDistance (cm), y DirectionalInscatteringExponent, z DirectionalInscatteringStartDistance (cm), w View.VolumetricFogMaxDistance (cm, 0 = no volume)
    dir_color: vec4<f32>,  // rgb View.DirectionalInscatteringColor (x sun luminance), w FogCutoffDistance (cm)
    color: vec4<f32>,      // rgb FogInscatteringColor
}

// Returns (inscattered radiance rgb, transmittance a). final = scene * a + rgb. `fwd` = unit camera forward (world), used by the volumetric exclusion
// (the height fog is excluded from the first VolumetricFogMaxDistance of view depth, the volume covers it: the excluded distance along the ray is
// VolumetricFogMaxDistance / cos(angle to the view axis)).
fn height_fog(f: HeightFogU, world_m: vec3<f32>, camera_m: vec3<f32>, to_sun: vec3<f32>, fwd: vec3<f32>) -> vec4<f32> {
    let FOG_DENSITY = f.p0.x;
    let FOG_FALLOFF = f.p0.y;
    let FOG_HEIGHT_CM = f.p0.z;
    let FOG_MAX_OPACITY = f.p0.w;
    let FOG_START_DISTANCE_CM = f.p1.x;
    let FOG_DIR_EXPONENT = f.p1.y;
    let FOG_DIR_START_CM = f.p1.z;
    let FOG_VOLUME_DISTANCE_CM = f.p1.w;
    let FOG_DIR_COLOR = f.dir_color.xyz;
    let FOG_CUTOFF_DISTANCE_CM = f.dir_color.w;
    let FOG_COLOR = f.color.xyz;
    let c = (world_m - camera_m) * 100.0;
    let cam_z = camera_m.y * 100.0;
    let len = max(length(c), 1e-6);
    let along = dot(c, fwd);
    // (the select keeps 0 * inf at along == 0 from becoming NaN when there is no volume: D3D `max` returns the non-NaN operand, WGSL leaves it undefined)
    let vol_exclude = select(0.0, max(len / along * FOG_VOLUME_DISTANCE_CM, 0.0), FOG_VOLUME_DISTANCE_CM > 0.0);
    let exclude = max(vol_exclude, FOG_START_DISTANCE_CM);
    let inv_len = 1.0 / len;
    var origin_density: f32;
    var ray_len: f32;
    var dz: f32;
    if (exclude > 0.0) {
        let t = min(exclude * inv_len, 1.0);   // ExcludeIntersectionTime (saturated: a point inside the volume has no height fog left)
        let to_excl_z = c.y * t;
        origin_density = exp2(-max(FOG_FALLOFF * (cam_z + to_excl_z - FOG_HEIGHT_CM), -127.0)) * FOG_DENSITY;
        ray_len = len * (1.0 - t);
        dz = c.y - to_excl_z;
    } else {
        origin_density = FOG_DENSITY * exp2(-max(FOG_FALLOFF * (cam_z - FOG_HEIGHT_CM), -127.0));
        ray_len = len;
        dz = c.y;
    }
    // RECOVERED line integral (1 - 2^-x) / x with x = max(FogHeightFalloff * (|dz| > 0.01 ? dz : 0.01), -127)
    let x = max(FOG_FALLOFF * select(0.01, dz, abs(dz) > 0.01), -127.0);
    let line = (1.0 - exp2(-x)) * origin_density / x;
    let optical = ray_len * line;
    let dir = c * inv_len;
    let dir_gain = pow(clamp(dot(dir, to_sun), 0.0, 1.0), FOG_DIR_EXPONENT);
    let dir_factor = 1.0 - min(exp2(-(max(ray_len - FOG_DIR_START_CM, 0.0) * line)), 1.0);
    var dir_in = FOG_DIR_COLOR * (dir_gain * dir_factor);
    var trans = max(min(exp2(-optical), 1.0), 1.0 - FOG_MAX_OPACITY);
    if (FOG_CUTOFF_DISTANCE_CM > 0.0 && FOG_CUTOFF_DISTANCE_CM < len) { dir_in = vec3<f32>(0.0); trans = 1.0; }
    return vec4<f32>(FOG_COLOR * (1.0 - trans) + dir_in, trans);
}

// Lighting shared by the scene shaders (scene.wgsl, static_scene.wgsl): camera/light blocks + group 0 bindings, cascade shadows,
// sky ambient, tangent-frame normal mapping, GGX and the fog/HDR tail. Prepended after common.wgsl by the Rust side.

struct Camera {
    view_proj: mat4x4<f32>,
    view: mat4x4<f32>,
    view_inverse: mat4x4<f32>,
    position: vec4<f32>,   // xyz eye, w time
    viewport: vec4<f32>,   // w, h, 1/w, 1/h
    proj: vec4<f32>,       // tan half fov x, tan half fov y, near, far
}
struct Light {
    sun_dir: vec4<f32>,        // unit vector towards the sun (world)
    sun_radiance: vec4<f32>,
    sky_radiance: vec4<f32>,
    shadow_matrix: array<mat4x4<f32>, 3>,   // world -> shadow uv (xy 0..1, y down) + depth 0..1
    cascade_far: vec4<f32>,    // xyz: view depth (m) where each cascade ends (nominal SplitFar), w: whole-scene fade FarDistance (CSM max or DF distance)
    cascade_texel: vec4<f32>,  // xyz: world metres per shadow texel, w: ShadowSharpen * 7 + 1
    shadow_params: vec4<f32>,  // x enabled, y shadow-mapped cascade count, z r.ShadowQuality (PCF kernel), w unused
    misc: vec4<f32>,           // x lit enabled, y material_debug bits, z shadow map size, w fog enabled
    cascade_ext: vec4<f32>,    // xyz: SplitFarFadeRegion (m) of each cascade (blend into the next), w: ShadowDistanceFadeoutFraction
    cascade_bias: vec4<f32>,   // xyz: ShaderDepthBias == ComputeTransitionSize (normalised depth units) of each cascade
    light_fn: vec4<f32>,       // directional light function (FLightFunctionPS): x volumetric-fog grey, y DisabledBrightness, z LightFunctionFadeDistance (m), w View.GameTime
    sky_sh: array<vec4<f32>, 7>,   // SKY LIGHT: View.SkyIrradianceEnvironmentMap x SkyLightColor (sky_light.rs), see sky_lookup
    fog: HeightFogU,           // TOD LIVE: this frame's height-fog view uniforms (common.wgsl, src/fog.rs HeightFogUniform)
    light_fn_world: vec4<f32>, // LIGHT FUNCTION: xyz renderer -> absolute UE offset (cm, light_function.rs), w 1 = light function on
}
@group(0) @binding(0) var<uniform> camera: Camera;
@group(0) @binding(1) var<uniform> light: Light;
@group(0) @binding(2) var shadow_map: texture_depth_2d_array;
@group(0) @binding(3) var shadow_samp: sampler_comparison;
// PERF (2026-10-06): point (non-filtering, clamp) sampler for the textureGather of the shadow depths (csm_gather)
@group(0) @binding(15) var shadow_point_samp: sampler;
@group(0) @binding(4) var tex_samp: sampler;

// ---- DISTANCE FIELD HOOK: ray-traced distance-field cascade + distance-field sky occlusion (distance_field.rs / distance_field_ao.rs) ----
struct DfU {
    sh0: vec4<f32>,   // x enabled, y MinDepth (cm), z MaxDepth (cm), w NearFadePlaneOffset (cm)
    sh1: vec4<f32>,   // x InvNearFadePlaneLength, y TanLightAngle, z TraceDistance (cm), w RayStartOffsetDepthScale
    sh2: vec4<f32>,   // x TwoSidedMeshDistanceBias (cm), y/z light tiles, w ShadowMaxObjectsPerTile
    sh3: vec4<f32>,   // xyz towards the light (DF space), w whole-scene shadow fade distance (m)
    world_to_shadow: mat4x4<f32>,
    ao0: vec4<f32>,   // x AO valid, y OcclusionExponent, z MinOcclusion, w OcclusionCombineMode
    ao1: vec4<f32>,   // xyz OcclusionTint (linear)
    ao2: vec4<f32>,   // ContrastAndNormalizeMulAdd
    ao3: vec4<f32>,   // AO buffer size, inverse size
    prev_view_proj: mat4x4<f32>,
    prev_eye: vec4<f32>,
    prev_fwd: vec4<f32>,
    sh4: vec4<f32>,   // DF SHADOW SCREEN PASS: xy RayTracedShadows size = floor(BufferSize / DownsampleFactor), z DownsampleFactor, w 1 = bilateral upsample (r.DFFullResolution 0)
}
@group(0) @binding(5) var<uniform> dfu: DfU;
@group(0) @binding(10) var df_ao: texture_2d<f32>;
// DF SHADOW SCREEN PASS (2026-10-06): the half-resolution ray-traced shadow factors of this frame (distance_field_shadow.wgsl, PF_G16R16F `RayTracedShadows`:
// x = the trace's Result, y = SceneDepth in cm). Replaces the trace inputs this block used to bind (objects 6, light tiles 7, atlas 8, its sampler 9: now the pass's own).
@group(0) @binding(16) var df_shadow_tex: texture_2d<f32>;

// renderer world (m, Y up) -> DF space (cm, Z up, UE axes)
fn df_space(p: vec3<f32>) -> vec3<f32> { return vec3<f32>(p.x, p.z, p.y) * 100.0; }
fn df_line_box(o: vec3<f32>, e: vec3<f32>, bmin: vec3<f32>, bmax: vec3<f32>) -> vec2<f32> {
    // LineBoxIntersect (Common.usf:1602)
    let inv = 1.0 / (e - o);
    let a = (bmin - o) * inv;
    let b = (bmax - o) * inv;
    let c = min(a, b);
    let f = max(a, b);
    return clamp(vec2<f32>(max(c.x, max(c.y, c.z)), min(f.x, min(f.y, f.z))), vec2<f32>(0.0), vec2<f32>(1.0));
}
// The pixel position of the fragment when the caller knows it (fx_resolve.wgsl fx_scene_world sets it from SV_Position); < 0 = project `world_pos` instead.
var<private> g_frag_xy: vec2<f32> = vec2<f32>(-1.0, -1.0);
// DF SHADOW SCREEN PASS (2026-10-06): DistanceFieldShadowingUpsamplePS (UE4.16 DistanceFieldShadowing.usf:616-667) at this pixel: the RayTracedShadows texels
// around it weighted bilinearly and by 1 / (|CornerDepth - SceneDepth| + 1e-4) (BILATERAL_UPSAMPLE && UPSAMPLE_REQUIRED), then FarBlendFactor (1: the ray-traced
// cascade is the last one, FadePlaneLength 0 -> InvFadePlaneLength 0) and NearBlendFactor = saturate((SceneDepth - (SplitNear - SplitNearFadeRegion)) /
// SplitNearFadeRegion). `scene_depth_cm` = this pixel's view depth (UE: CalcSceneDepth of the same pixel). UV = the full-resolution pixel centre UV (DrawRectangle
// maps the PS UV to it, odd sizes included); LowResBufferSize = floor(BufferSize / DOWNSAMPLE_FACTOR); the texel samples are at texel centres, so the bilinear
// sampler (AM_Clamp) returns the texels, read here with each corner clamped on its own. UE's quarter-texel offset (texel i was traced at full-res pixel 2i, the
// upsample takes it as centred at 2i + 1) is kept.
// All four corner weights 0 (fp16 SceneDepth overflowed: sky / far texels) gives 0 / 0 in UE; the NaN goes through EncodeLightAttenuation into the PF_B8G8R8A8
// light attenuation with BO_Min, where the float -> UNORM conversion turns it into 0 (D3D11): fully shadowed. Returned here as 0 for the same result.
fn df_shadow_upsample(world_pos: vec3<f32>, scene_depth_cm: f32) -> f32 {
    var uv: vec2<f32>;
    if (g_frag_xy.x >= 0.0) { uv = g_frag_xy * camera.viewport.zw; }
    else { let c = camera.view_proj * vec4<f32>(world_pos, 1.0); uv = vec2<f32>(c.x / c.w * 0.5 + 0.5, 0.5 - c.y / c.w * 0.5); }
    let low = dfu.sh4.xy;
    let lmax = vec2<i32>(low) - vec2<i32>(1);
    var out: f32;
    if (dfu.sh4.w > 0.5) {
        let t0 = floor(uv * low - 0.5);                            // the texel Corner00UV samples
        let corner00 = t0 / low + 0.5 * (1.0 / low);               // Corner00UV = floor(UV * LowResBufferSize - .5) / LowResBufferSize + .5 * LowResTexelSize
        let bw = (uv - corner00) * low;                            // BilinearWeights
        // PERF (2026-10-06): the four corner samples as two gathers of the 2x2 texels t0 .. t0 + 1 (x = Result, y = SceneDepth): exact texel values, each texel
        // clamped to the edge like UE's AM_Clamp sample (was four loads); gather order (0, 1), (1, 1), (1, 0), (0, 0) relative to t0 (csm_gather)
        let gc = (t0 + 1.0) / low;
        let gr = textureGather(0, df_shadow_tex, shadow_point_samp, gc);
        let gd = textureGather(1, df_shadow_tex, shadow_point_samp, gc);
        let values = vec4<f32>(gr.w, gr.z, gr.x, gr.y);           // TextureValues00 / 10 / 01 / 11 .x
        let corner_depths = abs(vec4<f32>(gd.w, gd.z, gd.x, gd.y));
        let cw = vec4<f32>((1.0 - bw.y) * (1.0 - bw.x), (1.0 - bw.y) * bw.x, bw.y * (1.0 - bw.x), bw.y * bw.x);
        let dw = 1.0 / (abs(corner_depths - vec4<f32>(scene_depth_cm)) + 0.0001);
        let fw = cw * dw;
        let sum = dot(fw, vec4<f32>(1.0));
        out = select(0.0, (fw.x * values.x + fw.y * values.y + fw.z * values.z + fw.w * values.w) / sum, sum > 0.0);
    } else {
        // r.DFFullResolution 1 (debug only, FN_DEBUG_DF_FULLRES): TDistanceFieldShadowingUpsamplePS<false>, the texel under the pixel
        out = textureLoad(df_shadow_tex, clamp(vec2<i32>(floor(uv * low)), vec2<i32>(0), lmax), 0).x;
    }
    let near_blend = clamp((scene_depth_cm - dfu.sh0.w) * dfu.sh1.x, 0.0, 1.0);
    return mix(1.0, out, near_blend);
}
