    vis = pow(vis, dfu.ao0.y);
    vis = mix(vis, 1.0, dfu.ao0.z);
    g_sky_vis = vis;
    let ln = sky_lookup(n);
    let diffuse = select(vec3<f32>(0.0), amb / max(ln, vec3<f32>(1e-6)), ln > vec3<f32>(1e-6));   // DiffuseColor
    let tint = dfu.ao1.xyz;
    g_sky_tint = tint * diffuse;
