            energy = energy * m / clamp(m + 0.5 * line_angle, 0.0, 1.0);
            let l01 = l.dir_min_rough.xyz * src_len;
            let l0 = to_light - 0.5 * l01;
            let a = src_len * src_len;
            let b = dot(r, l01);
            let t = clamp(dot(l0, b * r - l01) / (a - b * b), 0.0, 1.0);
            to_light = l0 + t * l01;
        }
        if (src_r > 0.0) {
            let sphere_angle = clamp(src_r * inv_dist, 0.0, 1.0);
            let e = m / clamp(m + 0.5 * sphere_angle, 0.0, 1.0);
            energy = energy * e * e;
            let closest = dot(to_light, r) * r;
            let c2r = closest - to_light;
            to_light = to_light + c2r * clamp(src_r * inverseSqrt(dot(c2r, c2r)), 0.0, 1.0);
        }
        ld = normalize(to_light);
        let h = normalize(v + ld);
        let nol_s = clamp(dot(n, ld), 0.0, 1.0);
        let nov = clamp(abs(dot(n, v)) + 1e-5, 0.0, 1.0);
        let noh = clamp(dot(n, h), 0.0, 1.0);
        let voh = clamp(dot(v, h), 0.0, 1.0);
        let d = ll_d_ggx(lobe_r, noh) * energy;
        let vis = ll_vis(lobe_r, nov, nol_s);
        let f = ll_f_schlick(spec_color, voh);
        let diffuse = diffuse_color * (1.0 / 3.14159265);
        let lcm = l.color_falloff.xyz * (nol * atten);
        var c = (diffuse + (d * vis) * f) * lcm;
        let sss = sm_subsurface_shading(id, custom, gbuffer_ao, ld, v, n) * l.color_falloff.xyz * atten;
        c = c + sss;
        var profile = 1.0;
        if (l.flags.y >= 0.0) {
            let neg = normalize(p - l.pos_inv_radius.xyz);
            let ang = asin(clamp(dot(neg, l.dir_min_rough.xyz), -1.0, 1.0));
            let rows = f32(textureDimensions(ll_ies).y);
            profile = textureSampleLevel(ll_ies, sky_refl_samp, vec2<f32>(ang / 3.14159265 + 0.5, (l.flags.y + 0.5) / rows), 0.0).r;
        }
        total = total + c * profile;
        g_ll_scatter = g_ll_scatter + (1.0 / 3.14159265) * lcm * profile;
    }
    return total;
}

// Textured static meshes (real 1.8 trees / rocks): vertex path shared by the scene pass and the shadow cascades.
// Group 1 = material (the same layout in both modules), vertex slot 0 = StaticVertex, slot 1 = per-instance record (instance step mode).
//
// WIND / SHAKE: the UE wind (SpeedTree-like WPO nodes) is NOT recovered. ASSUMED model: a lateral gust along WIND_DIR whose top-of-mesh
// displacement is `sway * height` metres, weighted by a quadratic height ramp (or the vertex colour .r when the material says the exported
// colour is a real bend weight), plus a high-frequency per-vertex flutter on masked foliage. The hit shake is the old runtime's
// prop_wobble (x offset growing linearly with height). The shadow pass evaluates the same function so shadows follow the sway.

struct StaticMaterial {
    tint: vec4<f32>,   // rgb linear multiplier, a translucency (two-sided light transmission)
    p0: vec4<f32>,     // x alpha cutoff, y masked (0/1), z two-sided (0/1), w has normal map (0/1)
    p1: vec4<f32>,     // x roughness, y sun specular scale, z sway (fraction of height), w flutter (metres)
    p2: vec4<f32>,     // x wind weight from vertex colour .r, y albedo from vertex colour rgb, zw unused
}
@group(1) @binding(0) var<uniform> smat: StaticMaterial;
@group(1) @binding(1) var t_base: texture_2d<f32>;
@group(1) @binding(2) var t_nrm: texture_2d<f32>;
@group(1) @binding(3) var s_static: sampler;

struct InstIn {
    @location(4) pos_scale: vec4<f32>,
    @location(5) rot_fade: vec4<f32>,   // cos yaw, sin yaw, fade, shake amplitude
    @location(6) wind: vec4<f32>,       // phase, time, sway multiplier, 1 / mesh height
}

const WIND_DIR: vec2<f32> = vec2<f32>(0.8, 0.6);

struct StaticPos { world: vec3<f32>, normal: vec3<f32> }

fn static_transform(pos: vec3<f32>, normal: vec3<f32>, color: vec4<f32>, inst: InstIn) -> StaticPos {
    let c = inst.rot_fade.x;
    let s = inst.rot_fade.y;
    // MIRRORFIX: a negative w = the instance is mirrored in its local X before the yaw (negative-determinant placement); the normal is mirrored with it
    // (the inverse transpose of diag(-1, 1, 1) is itself) and the pipeline reverses the culling (statics.rs)
    let scale = abs(inst.pos_scale.w);
    let m = select(vec3<f32>(1.0), vec3<f32>(-1.0, 1.0, 1.0), inst.pos_scale.w < 0.0);
    // yaw about +Y (glam Quat::from_rotation_y): x' = c x + s z, z' = -s x + c z
    let rot = mat3x3<f32>(vec3<f32>(c, 0.0, -s), vec3<f32>(0.0, 1.0, 0.0), vec3<f32>(s, 0.0, c));
    var world = rot * (pos * m * scale) + inst.pos_scale.xyz;
    let n = rot * (normal * m);

    let h01 = clamp(pos.y * inst.wind.w, 0.0, 1.0);
    var weight = h01 * h01;
    if (smat.p2.x > 0.5) { weight = color.r; }
    let t = inst.wind.y;
    let ph = inst.wind.x;
    let gust = sin(t * 1.1 + ph) * 0.6 + sin(t * 2.3 + ph * 1.7) * 0.4;
    let side = sin(t * 0.8 + ph * 0.5 + 1.3);
    let amp = smat.p1.z * inst.wind.z * scale / max(inst.wind.w, 1e-4);   // sway * height (m)
    world.x = world.x + (WIND_DIR.x * gust - WIND_DIR.y * side * 0.35) * amp * weight;
    world.z = world.z + (WIND_DIR.y * gust + WIND_DIR.x * side * 0.35) * amp * weight;
    if (smat.p1.w > 0.0) {
        let k = dot(pos, vec3<f32>(3.1, 5.3, 4.7)) + ph;
        world = world + vec3<f32>(sin(t * 7.0 + k), sin(t * 6.1 + k * 1.3) * 0.5, sin(t * 8.3 + k * 0.7)) * smat.p1.w * scale * weight;
    }
    // hit shake: lateral x offset growing linearly with height (fn_combat::prop_wobble)
    world.x = world.x + h01 * inst.rot_fade.w;
    return StaticPos(world, n);
}

// Static textured meshes in the HDR scene pass. Prepended: common.wgsl, lit_common.wgsl (globals, shadows, fog tail), static_common.wgsl.
// Shading = the prop path of scene.wgsl (sun diffuse x cascade visibility + sky hemisphere ambient with the ambient share in HDR alpha, height fog)
// with a base colour texture, optional normal map, alpha test, two-sided lighting and a simple GGX sun specular.

struct VsOut {
    @builtin(position) clip: vec4<f32>,
    @location(0) world_pos: vec3<f32>,
    @location(1) world_normal: vec3<f32>,
    @location(2) uv: vec2<f32>,
    @location(3) color: vec4<f32>,
    @location(4) fade: f32,
}

@vertex
fn vs_static(@location(0) pos: vec3<f32>, @location(1) normal: vec3<f32>, @location(2) uv: vec2<f32>, @location(3) color: vec4<f32>, inst: InstIn) -> VsOut {
    let sp = static_transform(pos, normal, color, inst);
    var o: VsOut;
    o.clip = camera.view_proj * vec4<f32>(sp.world, 1.0);
    o.world_pos = sp.world;
    o.world_normal = sp.normal;
    o.uv = uv;
    o.color = color;
    o.fade = inst.rot_fade.z;
    return o;
}

override EARLY_Z_MASKING: bool = false; // PREPASS
// Interleaved gradient noise (Jimenez): cheap, temporally stable screen-door pattern for the distance fade.
fn ign(p: vec2<f32>) -> f32 { return fract(52.9829189 * fract(dot(p, vec2<f32>(0.06711056, 0.00583715)))); }

@fragment
fn fs_static(in: VsOut) -> LitOut {
    let cam = camera.position.xyz;
    let tex = textureSample(t_base, s_static, in.uv);
    // Mip-aware alpha test: the CPU mip chain rescales the alpha of every level to keep the level-0 coverage at the cutoff (static_mesh.rs),
    // so a plain compare does not thin out or shimmer with distance.
    // PREPASS: with the depth pre-pass the clip tests ran there (cooked r.EarlyZPassOnlyMaterialMasking = True: the mask is evaluated only in the early Z
    // pass, the base pass then draws with CF_Equal and no clip, BasePassRendering.cpp / DepthRendering.cpp); EARLY_Z_MASKING = true on the lit pipelines that follow the pre-pass (statics.rs).
    if (!EARLY_Z_MASKING) {
    if (smat.p0.y > 0.5 && tex.a < smat.p0.x) { discard; }
    if (in.fade < 0.999 && ign(in.clip.xy) > in.fade) { discard; }
    }

    var albedo = tex.rgb * smat.tint.rgb;
    if (smat.p2.y > 0.5) { albedo = albedo * in.color.rgb; }
    let two_sided = smat.p0.z > 0.5;
    let v = normalize(cam - in.world_pos);
    var n = normalize(in.world_normal);
    // Two-sided surfaces light the side that faces the viewer (independent of the exported winding): flip the normal on back faces.
    if (two_sided && dot(n, v) < 0.0) { n = -n; }
    if (smat.p0.w > 0.5) {
        n = perturb_normal(n, in.world_pos, in.uv, unpack_normal(textureSample(t_nrm, s_static, in.uv)));
    }
    let sun = light.sun_dir.xyz;
    let ndl = dot(n, sun);
    var lit = albedo;
    var amb = vec3<f32>(0.0);
    if (light.misc.x > 0.5) {
        // Receiver lookups offset towards the sun side of the surface (so a leaf lit from behind does not shadow itself); the slope bias
        // uses |n.l|.
        let n_sun = select(-n, n, ndl >= 0.0);
        let front = max(ndl, 0.0);
        var back = 0.0;
        if (two_sided) { back = max(-ndl, 0.0) * smat.tint.a; }
        let vis = sun_visibility(in.world_pos, n_sun, abs(ndl));
        amb = albedo * ambient_light(n);
        lit = albedo * light.sun_radiance.xyz * (front + back) * vis + amb;
        // a dielectric, SpecularColor = 0.08 * Specular (the material's Specular, p1.y), roughness p1.x. The sun lobe uses UE's F_Schlick on that colour
        // (lit_common.wgsl ggx_spec_color; was F0 0.04 with the whole lobe scaled by Specular, i.e. the grazing term too)
        let spec_color = vec3<f32>(0.08 * smat.p1.y);
        if (ndl > 0.0) {
            lit = lit + light.sun_radiance.xyz * 3.14159265 * ggx_spec_color(n, v, sun, smat.p1.x, spec_color) * vis;
        }
        lit = lit + local_lighting(in.world_pos, n, v, albedo, spec_color, smat.p1.x, SM_DEFAULT_LIT, vec4<f32>(0.0), 1.0);
        // SKY REFLECTION HOOK (lit_common.wgsl reflection_inputs, applied by the deferred reflection pass)
        reflection_inputs(n, v, in.world_pos, spec_color, smat.p1.x, 1.0);
    }
    return lit_out(output_hdr(lit, amb, in.world_pos, cam));
}

// PREPASS (UE4.16 FDeferredShadingSceneRenderer::RenderPrePass, cooked RendererSettings r.EarlyZPass = 2 = opaque AND masked; DepthRendering.cpp
// TDepthOnlyVS / FDepthOnlyPS): every static mesh draws its depth first, with the clip tests of the lit pass (opacity mask, distance-fade dither); the lit
// pipelines then test CF_Equal without clip (r.EarlyZPassOnlyMaterialMasking = True). The pre-pass runs vs_static itself (same vertex stage = same depth).
@fragment
fn fs_static_depth(in: VsOut) {
    let tex = textureSample(t_base, s_static, in.uv);
    if (smat.p0.y > 0.5 && tex.a < smat.p0.x) { discard; }
    if (in.fade < 0.999 && ign(in.clip.xy) > in.fade) { discard; }
}

// OUTLINE (custom depth): `ABuildingActor` vfunc_259 @1404823b0 turns on the components' custom depth with the custom stencil value of
// `SelectionOutlineID_CodeReferenced`; UE4.16 draws them depth-only (clip tests of the material, no distance-fade dither) into the CustomDepth target and
// writes the stencil value. The port keeps the stencil in an Rg8Uint colour target (the post program reads `.y`, the X24_G8 stencil view's channel).
override CUSTOM_STENCIL: f32 = 0.0;
@fragment
fn fs_static_custom(in: VsOut) -> @location(0) vec4<u32> {
    let tex = textureSample(t_base, s_static, in.uv);
    if (smat.p0.y > 0.5 && tex.a < smat.p0.x) { discard; }
    let s = u32(CUSTOM_STENCIL);
    return vec4<u32>(s, s, 0u, 0u);
}
