    lit = lit + g_sky_tint;
    dl = dl + sss_luma(g_sky_tint);
    var fog = vec4<f32>(0.0, 0.0, 0.0, 1.0);
    if (light.misc.w > 0.5) { fog = height_fog(light.fog, world, cam, light.sun_dir.xyz, -camera.view_inverse[2].xyz); }
