    sun_dir: vec4<f32>,
    sun_radiance: vec4<f32>,
    sky_radiance: vec4<f32>,
    shadow_matrix: array<mat4x4<f32>, 3>,
    cascade_far: vec4<f32>,
    cascade_texel: vec4<f32>,
    shadow_params: vec4<f32>,
    misc: vec4<f32>,
    cascade_ext: vec4<f32>,
    cascade_bias: vec4<f32>,
