// Shared WGSL helpers, prepended to every scene/sky shader by the Rust side (WGSL has no #include).
// Ported from FortniteRuntime/src/shaders/common.glsl + fog.glsl.
// All colour maths in the scene passes is linear; encoding to sRGB happens once, in post.wgsl.

fn decode_srgb(x: f32) -> f32 {
    if (x <= 0.04045) { return x / 12.92; }
    return pow((x + 0.055) / 1.055, 2.4);
}
fn encode_srgb(x: f32) -> f32 {
    if (x <= 0.0031308) { return x * 12.92; }
    return 1.055 * pow(x, 1.0 / 2.4) - 0.055;
}
fn to_linear(v: vec3<f32>) -> vec3<f32> { return vec3<f32>(decode_srgb(v.x), decode_srgb(v.y), decode_srgb(v.z)); }
fn to_srgb(v: vec3<f32>) -> vec3<f32> { return vec3<f32>(encode_srgb(v.x), encode_srgb(v.y), encode_srgb(v.z)); }
fn luma709(c: vec3<f32>) -> f32 { return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722)); }

// Unreal-style ExponentialHeightFog: the compiled TExponentialHeightFogPS<DirectionalLightInscatteringAndVolumetricFog> of the 1.8 global shader cache
// (ported in src/fog.rs `HeightFogPs::eval`, which this mirrors line for line), evaluated per fragment. World units here are metres (GL, Y up);
// the maths runs in Unreal units (cm, Z up = renderer Y).
// TOD LIVE: the values are PER-FRAME uniform data (src/fog.rs HeightFogUniform, the live clock's ExpHeightFogValues phase blend), not baked constants: the
// including shader passes its block (lit_common.wgsl `light.fog`, sky_common.wgsl `sky.fog`). Density / falloff carry the engine /1000 remap.
struct HeightFogU {
    p0: vec4<f32>,         // x FogDensity, y FogHeightFalloff (both /1000), z FogHeight (cm), w FogMaxOpacity
    p1: vec4<f32>,         // x StartDistance (cm), y DirectionalInscatteringExponent, z DirectionalInscatteringStartDistance (cm), w View.VolumetricFogMaxDistance (cm, 0 = no volume)
    dir_color: vec4<f32>,  // rgb View.DirectionalInscatteringColor (x sun luminance), w FogCutoffDistance (cm)
    color: vec4<f32>,      // rgb FogInscatteringColor
}

// Returns (inscattered radiance rgb, transmittance a). final = scene * a + rgb. `fwd` = unit camera forward (world), used by the volumetric exclusion
// (the height fog is excluded from the first VolumetricFogMaxDistance of view depth, the volume covers it: the excluded distance along the ray is
// VolumetricFogMaxDistance / cos(angle to the view axis)).
fn height_fog(f: HeightFogU, world_m: vec3<f32>, camera_m: vec3<f32>, to_sun: vec3<f32>, fwd: vec3<f32>) -> vec4<f32> {
    let FOG_DENSITY = f.p0.x;
    let FOG_FALLOFF = f.p0.y;
    let FOG_HEIGHT_CM = f.p0.z;
    let FOG_MAX_OPACITY = f.p0.w;
    let FOG_START_DISTANCE_CM = f.p1.x;
    let FOG_DIR_EXPONENT = f.p1.y;
    let FOG_DIR_START_CM = f.p1.z;
    let FOG_VOLUME_DISTANCE_CM = f.p1.w;
    let FOG_DIR_COLOR = f.dir_color.xyz;
    let FOG_CUTOFF_DISTANCE_CM = f.dir_color.w;
    let FOG_COLOR = f.color.xyz;
    let c = (world_m - camera_m) * 100.0;
    let cam_z = camera_m.y * 100.0;
    let len = max(length(c), 1e-6);
    let along = dot(c, fwd);
    // (the select keeps 0 * inf at along == 0 from becoming NaN when there is no volume: D3D `max` returns the non-NaN operand, WGSL leaves it undefined)
    let vol_exclude = select(0.0, max(len / along * FOG_VOLUME_DISTANCE_CM, 0.0), FOG_VOLUME_DISTANCE_CM > 0.0);
    let exclude = max(vol_exclude, FOG_START_DISTANCE_CM);
    let inv_len = 1.0 / len;
    var origin_density: f32;
    var ray_len: f32;
    var dz: f32;
    if (exclude > 0.0) {
        let t = min(exclude * inv_len, 1.0);   // ExcludeIntersectionTime (saturated: a point inside the volume has no height fog left)
        let to_excl_z = c.y * t;
        origin_density = exp2(-max(FOG_FALLOFF * (cam_z + to_excl_z - FOG_HEIGHT_CM), -127.0)) * FOG_DENSITY;
        ray_len = len * (1.0 - t);
        dz = c.y - to_excl_z;
    } else {
        origin_density = FOG_DENSITY * exp2(-max(FOG_FALLOFF * (cam_z - FOG_HEIGHT_CM), -127.0));
        ray_len = len;
        dz = c.y;
    }
    // RECOVERED line integral (1 - 2^-x) / x with x = max(FogHeightFalloff * (|dz| > 0.01 ? dz : 0.01), -127)
    let x = max(FOG_FALLOFF * select(0.01, dz, abs(dz) > 0.01), -127.0);
    let line = (1.0 - exp2(-x)) * origin_density / x;
    let optical = ray_len * line;
    let dir = c * inv_len;
    let dir_gain = pow(clamp(dot(dir, to_sun), 0.0, 1.0), FOG_DIR_EXPONENT);
    let dir_factor = 1.0 - min(exp2(-(max(ray_len - FOG_DIR_START_CM, 0.0) * line)), 1.0);
    var dir_in = FOG_DIR_COLOR * (dir_gain * dir_factor);
    var trans = max(min(exp2(-optical), 1.0), 1.0 - FOG_MAX_OPACITY);
    if (FOG_CUTOFF_DISTANCE_CM > 0.0 && FOG_CUTOFF_DISTANCE_CM < len) { dir_in = vec3<f32>(0.0); trans = 1.0; }
    return vec4<f32>(FOG_COLOR * (1.0 - trans) + dir_in, trans);
}

// Fullscreen post-process: bloom, exposure, vignette, white balance, UE 4.16 filmic tonemapper, sRGB encode.
// Port of post.frag. Order follows UE4's tonemapper (bloom added to scene colour, exposure, vignette, then the colour-grading
// stage = white balance + ACES film path), every stage is an APPROXIMATION unless marked RECOVERED.
// Also contains the HDR mip downsample (bloom + exposure metering) and the exposure-adaptation compute shader.
// Common helpers (srgb) are prepended from common.wgsl.

struct PostParams {
    wb0: vec4<f32>, wb1: vec4<f32>, wb2: vec4<f32>,   // white balance matrix columns (linear sRGB -> linear sRGB)
    film_stw: vec4<f32>,       // slope, toe, shoulder
    film_clip: vec4<f32>,      // black clip, white clip
    bloom: vec4<f32>,          // intensity, threshold, enabled
    vignette: vec4<f32>,       // intensity, enabled
    ao: vec4<f32>,             // legacy block (intensity, radius m, enabled, bias): unused since the UE 4.16 SSAO (ssao_ue.rs) has its own uniform
    proj: vec4<f32>,           // tan(half fov x), tan(half fov y), near, far
    view: vec4<f32>,           // width, height, display_exponent, debug_mode
    backdrop: vec4<f32>,       // pause-menu backdrop: dim (0..1), blur (0..1)
    grade_sat: vec4<f32>,      // colour-grading saturation per region (shadows, midtones, highlights) = region * global ColorSaturation
    grade_contrast: vec4<f32>, // ColorContrast per region
    grade_gamma: vec4<f32>,    // ColorGamma per region
    grade_range: vec4<f32>,    // ColorCorrectionShadowsMax, ColorCorrectionHighlightsMin, 1 = contrast/gamma not identity, LUT output scale (1.05)
    // SCALABILITY: x = r.Tonemapper.Sharpen / 6 (TonemapperParams.y, PostProcessTonemap.cpp:950-953), y = 1: grain quantization
    // (r.Tonemapper.GrainQuantization > 0, PostProcessTonemap.cpp:609-617), zw = GrainRandomFull.xy (GrainRandomFromFrame, PostProcessTonemap.h:34-38)
    tonemap_ext: vec4<f32>,
    // POSTFX SETTINGS (effect_settings.rs): scene colour fringe, xy = FringeUVParams (.x scales the G sample position, .y the R one about the view
    // centre), z = 1 when USE_COLOR_FRINGE (SceneFringeIntensity > 0.01 after r.SceneColorFringeQuality, PostProcessTonemap.cpp:620)
    fringe: vec4<f32>,
    scene_tint: vec4<f32>,
}
struct ExposureState { ev: f32, target_ev: f32, exposure: f32, avg_luminance: f32 }

@group(0) @binding(0) var<uniform> pp: PostParams;
@group(0) @binding(1) var scene: texture_2d<f32>;
@group(0) @binding(2) var depth_tex: texture_depth_2d;
@group(0) @binding(3) var<storage, read> exposure_state: ExposureState;
@group(0) @binding(4) var lin_samp: sampler;
// BLOOM HOOK: the bloom image of fn_postfx::bloom (UE 4.16 chain: SceneColorHalfRes -> 5 downsamples -> Bloom6..1 Gaussians, tint / 6),
// half resolution, NOT exposed, NOT multiplied by BloomIntensity (PostprocessInput1 of FPostProcessTonemapPS).
@group(0) @binding(5) var bloom_tex: texture_2d<f32>;
// COLOR LUT (GLOBAL LOOK): the 32^3 colour-grading LUT of FCombineLUTs (color_lut.rs / color_lut.wgsl, rebuilt every frame from `pp`), = OutDeviceColor / 1.05
// rounded to 10 bits. Binding 10 because ssao_apply.wgsl (which also includes this file) owns 6..9.
@group(0) @binding(10) var color_lut: texture_3d<f32>;

struct VsOut { @builtin(position) clip: vec4<f32>, @location(0) uv: vec2<f32> }   // uv: GL convention (y up)

@vertex
fn vs_main(@builtin(vertex_index) i: u32) -> VsOut {
    var o: VsOut;
    let x = f32(i32(i & 1u) * 4 - 1);
    let y = f32(i32((i >> 1u) & 1u) * 4 - 1);
    // full-screen triangle: (-1,-1), (3,-1), (-1,3)
    o.clip = vec4<f32>(x, y, 0.0, 1.0);
    o.uv = vec2<f32>(x, y) * 0.5 + 0.5;
    return o;
}

fn tc(p: vec2<f32>) -> vec2<f32> { return vec2<f32>(p.x, 1.0 - p.y); }   // GL uv -> texture coordinate

// ---- AO: the screen-space AO is UE 4.16's (ssao_ue.rs / ssao_ue.wgsl), applied by ssao_apply.wgsl before fog / translucency ----

// ---- Bloom (BLOOM HOOK): the chain runs in fn_postfx::bloom; the tonemapper only samples it (bilinear, screen uv) and scales it by
// ColorScale1 = BloomIntensity (+ BloomDirtMask tint * mask; the Athena volumes set no BloomDirtMask texture -> BlackDummy -> 0). ----
fn bloom_color(uv: vec2<f32>) -> vec3<f32> {
    return textureSampleLevel(bloom_tex, lin_samp, tc(uv), 0.0).rgb * pp.bloom.x;
}

// ---- Filmic tonemapper curve (UE4 FilmToneMap structure: log-domain toe/straight/shoulder blend) ----
fn film_curve(untonemapped: vec3<f32>) -> vec3<f32> {
    let slope = pp.film_stw.x;
    let toe = pp.film_stw.y;
    let shoulder = pp.film_stw.z;
    let black = pp.film_clip.x;
    let white = pp.film_clip.y;
    let toe_scale = 1.0 + black - toe;
    let shoulder_scale = 1.0 + white - shoulder;
    let in_match = 0.18;
    let out_match = 0.18;
    var toe_match: f32;
    if (toe > 0.8) { toe_match = (1.0 - toe - out_match) / slope + log(in_match) / 2.302585093; }
    else {
        let bt = (out_match + black) / toe_scale - 1.0;
        toe_match = log(in_match) / 2.302585093 - 0.5 * log((1.0 + bt) / (1.0 - bt)) * (toe_scale / slope);
    }
    let straight_match = (1.0 - toe) / slope - toe_match;
    let shoulder_match = shoulder / slope - straight_match;
    let log_color = log(max(untonemapped, vec3<f32>(1e-10))) / 2.302585093;
    let straight = slope * (log_color + straight_match);
    var toe_color = -black + 2.0 * toe_scale / (1.0 + exp(-2.0 * (slope / toe_scale) * (log_color - toe_match)));
    var shoulder_color = (1.0 + white) - 2.0 * shoulder_scale / (1.0 + exp(2.0 * (slope / shoulder_scale) * (log_color - shoulder_match)));
    toe_color = select(straight, toe_color, log_color < vec3<f32>(toe_match));
    shoulder_color = select(straight, shoulder_color, log_color > vec3<f32>(shoulder_match));
    var t = clamp((log_color - toe_match) / (shoulder_match - toe_match), vec3<f32>(0.0), vec3<f32>(1.0));
    if (shoulder_match < toe_match) { t = 1.0 - t; }
    t = (3.0 - 2.0 * t) * t * t;
    return mix(toe_color, shoulder_color, t);
}
// ACES matrices exactly as compiled into the UE 4.16 CombineLUTs shader (WGSL mat3x3 is column-major, so each constructor lists
// the transposed rows of the HLSL dp3 constants). They include the D65 <-> D60 adaptation.
const SRGB_TO_AP0 = mat3x3<f32>(0.439701, 0.089792, 0.017544, 0.382978, 0.813423, 0.111544, 0.177335, 0.096762, 0.870704);
const AP0_TO_AP1 = mat3x3<f32>(1.451439, -0.076554, 0.008316, -0.236511, 1.176230, -0.006032, -0.214929, -0.099676, 0.997716);
const AP1_TO_SRGB = mat3x3<f32>(1.705052, -0.130257, -0.024003, -0.621791, 1.140803, -0.128969, -0.083258, -0.010549, 1.152972);
const AP1_LUMA = vec3<f32>(0.2722287168, 0.6740817658, 0.0536895174);
const RRT_SAT_FACTOR: f32 = 0.96;   // RECOVERED: 0.96 / 0.93 are literals in the 4.16 film path
const ODT_SAT_FACTOR: f32 = 0.93;
// LUT domain: LogToLin(0) .. LogToLin(1), LogToLin(x) = 0.18 * 2^((x - 0.434018) * 14). RECOVERED.
const LUT_MIN: f32 = 0.0026677086;
const LUT_MAX: f32 = 43.707738;

// CombineLUTs colour correction, RECOVERED from the 4.16 CombineLUTs DXBC (shader 1182809): sRGB -> AP1, AP1 luma, shadows / midtones /
// highlights regions (weights 1 - smoothstep(luma / ShadowsMax), smoothstep((luma - HighlightsMin) / (1 - HighlightsMin)), remainder),
// each max(luma + sat * (c - luma), 0). ColorSaturationShadows = Midtones = 1.25 (TODM_A), Highlights 1.0, ShadowsMax 0.09 and
// HighlightsMin 0.5 (exe ctor defaults); contrast/gamma/gain/offset stay identity. Mirrors tonemap::color_grade.
const SRGB_TO_AP1 = mat3x3<f32>(0.613191, 0.070207, 0.020619, 0.339512, 0.916336, 0.109567, 0.047366, 0.013450, 0.869607);
fn grade_region(ap1: vec3<f32>, luma: f32, sat: f32, contrast: f32, gamma: f32) -> vec3<f32> {
    var w = max(vec3<f32>(luma) + (ap1 - vec3<f32>(luma)) * sat, vec3<f32>(0.0));
    if (pp.grade_range.z > 0.5) {
        w = pow(w * (1.0 / 0.18), vec3<f32>(contrast)) * 0.18;
        w = pow(w, vec3<f32>(1.0 / gamma));
    }
    return w;
}
// ColorCorrectAll of the 4.16 CombineLUTs: three regions with their own saturation / contrast / gamma (gain 1, offset 0 in every phase).
// Per-phase values come from tonemap::PostSettings (Evening = sunset: shadows 1.5, midtones 1.15).
fn color_grade(c: vec3<f32>) -> vec3<f32> {
    let ap1 = SRGB_TO_AP1 * c;
    let luma = dot(ap1, AP1_LUMA);
    let xs = clamp(luma / pp.grade_range.x, 0.0, 1.0);
    let xh = clamp((luma - pp.grade_range.y) / (1.0 - pp.grade_range.y), 0.0, 1.0);
    let sw = 1.0 - xs * xs * (3.0 - 2.0 * xs);
    let hw = xh * xh * (3.0 - 2.0 * xh);
    let mw = 1.0 - sw - hw;
    let shadows = grade_region(ap1, luma, pp.grade_sat.x, pp.grade_contrast.x, pp.grade_gamma.x);
    let mids = grade_region(ap1, luma, pp.grade_sat.y, pp.grade_contrast.y, pp.grade_gamma.y);
    let highs = grade_region(ap1, luma, pp.grade_sat.z, pp.grade_contrast.z, pp.grade_gamma.z);
    return AP1_TO_SRGB * (shadows * sw + mids * mw + highs * hw);
}
// ACES RRT hue-dependent red modifier (RECOVERED, 4.16): pivot 0.03, scale 0.82, hue 0, width 135.
fn aces_red_modifier(aces_in: vec3<f32>) -> vec3<f32> {
    var aces = aces_in;
    let minrgb = min(aces.r, min(aces.g, aces.b));
    let maxrgb = max(aces.r, max(aces.g, aces.b));
    let saturation = (max(maxrgb, 1e-10) - max(minrgb, 1e-10)) / max(maxrgb, 1e-2);
    var hue = 0.0;
    if (!(aces.r == aces.g && aces.g == aces.b)) {
        hue = degrees(atan2(1.7320508 * (aces.g - aces.b), 2.0 * aces.r - aces.g - aces.b));
        if (hue < 0.0) { hue = hue + 360.0; }
    }
    let centered = select(hue, hue - 360.0, hue > 180.0);
    let w = smoothstep(0.0, 1.0, 1.0 - abs(2.0 * centered / 135.0));
    aces.r = aces.r + w * w * saturation * (0.03 - aces.r) * (1.0 - 0.82);
    return aces;
}
// COLOR LUT (GLOBAL LOOK): CombineLUTsCommon of the 1.8 DXBC (GlobalShaderCache#1182809) for one LUT-domain linear colour, up to OutDeviceColor (the
// caller stores it / 1.05): WhiteBalance, ColorGrade (ColorCorrectAll in AP1), FilmToneMap (sRGB -> AP0, ACES red modifier, AP0 -> AP1 clamped, RRT sat
// 0.96, Film* curve, ODT sat 0.93), AP1 -> sRGB clamped, ColorCorrection (MappingPolynomial: r.Color.Min/Mid/Max not in the cooked ini -> 0 / 0.5 / 1 =
// identity), lerp(FilmColor * ColorScale, OverlayColor, a) (no fade: identity), pow(max(0, x), InverseGamma.y) (y = 2.2 / DisplayGamma = view.z),
// LinearToSrgb (OutputDevice 0: r.HDR.Display.OutputDevice 0 and r.TonemapperGamma 0 are not in the cooked ini).
fn lut_device_color(linear: vec3<f32>) -> vec3<f32> {
    let wb = mat3x3<f32>(pp.wb0.xyz, pp.wb1.xyz, pp.wb2.xyz);
    let graded = color_grade(wb * linear);
    var ap0 = SRGB_TO_AP0 * graded;
    ap0 = aces_red_modifier(ap0);
    var ap1 = max(AP0_TO_AP1 * ap0, vec3<f32>(0.0));
    ap1 = mix(vec3<f32>(dot(ap1, AP1_LUMA)), ap1, RRT_SAT_FACTOR);
    var toned = film_curve(ap1);
    toned = max(mix(vec3<f32>(dot(toned, AP1_LUMA)), toned, ODT_SAT_FACTOR), vec3<f32>(0.0));
    let film = max(AP1_TO_SRGB * toned, vec3<f32>(0.0));
    return to_srgb(pow(film, vec3<f32>(pp.view.z)));
}
// ColorLookupTable (PostProcessTonemap.usf:68, 1.8 DXBC FPostProcessTonemapPS0 #1070630): LUTEncodedColor = LinToLog(c) = saturate(log2(c) / 14 + 0.610727)
// (no `+ LogToLin(0)` in the 1.8 build), UVW = enc * 31/32 + 0.5/32, trilinear clamp sample, * 1.05. log2 of 0 / negative (NaN) saturates to 0 like D3D.
fn color_lookup_table(c: vec3<f32>) -> vec3<f32> {
    let enc = clamp(log2(max(c, vec3<f32>(0.0))) * (1.0 / 14.0) + vec3<f32>(0.610727), vec3<f32>(0.0), vec3<f32>(1.0));
    let uvw = enc * (31.0 / 32.0) + vec3<f32>(0.5 / 32.0);
    return textureSampleLevel(color_lut, lin_samp, uvw, 0.0).rgb * 1.05;
}
// UE ComputeVignetteMask, RECOVERED from the 4.16 tonemap VS/PS: natural cos^4 vignette, circle-space position normalised so the
// screen corner sits at radius sqrt(2) for every aspect: p = sqrt2/sqrt(1+a^2) * (ndc.x, a*ndc.y), a = height/width; mask = 1/(1+|p I|^2)^2.
fn vignette_mask(uv: vec2<f32>) -> f32 {
    let a = pp.view.y / pp.view.x;
    let p = (uv * 2.0 - 1.0) * vec2<f32>(1.0, a) * (1.4142135624 / sqrt(1.0 + a * a)) * pp.vignette.x;
    let t = 1.0 / (1.0 + dot(p, p));
    return t * t;
}

// Pause-menu backdrop blur: trilinear taps of the HDR mip chain (box-filtered), 3x3 kernel at lod = blur * 5.
fn blurred_scene(uv: vec2<f32>) -> vec4<f32> {
    let lod = clamp(pp.backdrop.y, 0.0, 1.0) * 5.0;
    let texel = 1.0 / vec2<f32>(textureDimensions(scene, i32(floor(lod))));
    var acc = vec4<f32>(0.0);
    var wsum = 0.0;
    for (var y = -1; y <= 1; y = y + 1) {
        for (var x = -1; x <= 1; x = x + 1) {
            let w = select(1.0, 2.0, x == 0) * select(1.0, 2.0, y == 0);
            acc = acc + textureSampleLevel(scene, lin_samp, tc(uv + vec2<f32>(f32(x), f32(y)) * texel * 1.5), lod) * w;
            wsum = wsum + w;
        }
    }
    return acc / wsum;
}

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    let uv = in.uv;
    let debug_mode = i32(pp.view.w);
    let exposure = exposure_state.exposure;
    var scene_sample = textureSampleLevel(scene, lin_samp, tc(uv), 0.0);
    // USE_COLOR_FRINGE (PostProcessTonemap.usf:155-159 / :332-341): FringeUV = ScreenPosToUV(ScreenPos * FringeUVParams.{r,g}); R from FringeUV.zw (scale
    // .g = 1/(1+Offset*ScaleR)), G from FringeUV.xy (scale .r), B from the unshifted UV (bilinear clamp sampler, no grain jitter: GrainJitter 0)
    if (pp.fringe.z > 0.5) {
        let sp = uv * 2.0 - 1.0;
        scene_sample.r = textureSampleLevel(scene, lin_samp, tc(sp * pp.fringe.y * 0.5 + 0.5), 0.0).r;
        scene_sample.g = textureSampleLevel(scene, lin_samp, tc(sp * pp.fringe.x * 0.5 + 0.5), 0.0).g;
    }
    let blurred = pp.backdrop.y > 0.0;
    if (blurred) { scene_sample = blurred_scene(uv); }
    var c = scene_sample.rgb;
    // USE_SHARPEN (PostProcessTonemap.usf:357-412): Luminance (0.3, 0.59, 0.11) of the centre and of 4 neighbours (-1,0) (1,0) (-1,-1) (-1,1),
    // EdgeMask = saturate(1 - ExposureScale * max|A0 - L|), SceneColor += ((C1 + C2 + C3 + C4) - 4 SceneColor) * (-EdgeMask * Sharpen / 6)
    if (pp.tonemap_ext.x > 0.0 && !blurred) {
        let texel = 1.0 / pp.view.xy;
        let c1 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(-1.0, 0.0) * texel, 0.0).rgb;
        let c2 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(1.0, 0.0) * texel, 0.0).rgb;
        let c3 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(-1.0, -1.0) * texel, 0.0).rgb;
        let c4 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(-1.0, 1.0) * texel, 0.0).rgb;
        let lw = vec3<f32>(0.3, 0.59, 0.11);
        let a0 = dot(c, lw);
        let ln = vec4<f32>(dot(c1, lw), dot(c2, lw), dot(c3, lw), dot(c4, lw));
        let d = abs(vec4<f32>(a0) - ln);
        let hdr_edge = exposure_state.exposure * max(max(d.x, d.y), max(d.z, d.w));
        let edge_mask = clamp(1.0 - hdr_edge, 0.0, 1.0);
        let lerp_factor = -edge_mask * pp.tonemap_ext.x;
        c = c + ((c1 + c2 + c3 + c4) - c * 4.0) * lerp_factor;
    }
    // AO ORDER: the screen-space AO is no longer applied here; ssao_apply.wgsl (ssao_pass.rs) applies it to the HDR scene right after the opaque
    // scene, before fog / translucency / bloom / the histogram, matching UE 4.16 where SSAO only acts inside the lighting.
    let raw_scene = scene_sample.rgb;
    var bloom = vec3<f32>(0.0);
    if (pp.bloom.z > 0.5 && !blurred) { bloom = bloom_color(uv); }
    // PostProcessTonemap.usf: LinearColor = SceneColor * ColorScale0 + CombinedBloom * ColorScale1; LinearColor *= ExposureScale
    c = (c * pp.scene_tint.rgb + bloom) * exposure;
    if (pp.vignette.y > 0.5) { c = c * vignette_mask(uv); }
    if (debug_mode == 5) { return vec4<f32>(vec3<f32>(vignette_mask(uv)), 1.0); }
    if (debug_mode == 2) { return vec4<f32>(clamp(raw_scene, vec3<f32>(0.0), vec3<f32>(1.0)), 1.0); }   // the AO pass wrote the raw AO term in this mode
    if (debug_mode == 3) { return vec4<f32>(to_srgb(clamp(bloom * 4.0, vec3<f32>(0.0), vec3<f32>(1.0))), 1.0); }
    if (debug_mode == 4) { return vec4<f32>(to_srgb(clamp(c, vec3<f32>(0.0), vec3<f32>(1.0))), 1.0); }
    // The tonemap pass samples the 32^3 colour-grading LUT with saturate(log2(c)/14 + 0.610727): input clamped to the LUT domain
    // before white balance (RECOVERED). Direct evaluation replaces the trilinear 32^3 interpolation; the grain dither is applied below when the level enables it.
    if (debug_mode == 1) {
        let wb = mat3x3<f32>(pp.wb0.xyz, pp.wb1.xyz, pp.wb2.xyz);
        return vec4<f32>(to_srgb(clamp(color_grade(wb * clamp(c, vec3<f32>(LUT_MIN), vec3<f32>(LUT_MAX))), vec3<f32>(0.0), vec3<f32>(1.0))), 1.0);
    }
    // COLOR LUT (GLOBAL LOOK): the colour transform (white balance, grading, ACES film path, display gamma, sRGB) comes from the 32^3 LUT that
    // color_lut.wgsl bakes from the same `pp` block (OutDeviceColor / 1.05, 10-bit), sampled trilinearly and * 1.05 (ColorLookupTable). The old direct
    // evaluation lacked CombineLUTs' / 1.05 and came out 5 % brighter (mid grey 123 instead of 117 / 255, highlights clipped at 0.952).
    var out_c = color_lookup_table(c);
    // USE_GRAIN_QUANTIZATION (PostProcessTonemap.usf:474-481): Grain = frac(sin(GrainUV.x + GrainUV.y * 543.31) * 493013) with GrainUV = TexCoord +
    // GrainRandomFull.xy; OutDeviceColor += Grain / 256 - 0.5 / 256 (after the LUT, before the 8-bit write: DXBC `mad r0.xyz, lut, 1.05, grain`)
    if (pp.tonemap_ext.y > 0.5) {
        let guv = tc(uv) + pp.tonemap_ext.zw;
        let grain = fract(sin(guv.x + guv.y * 543.31) * 493013.0);
        out_c = out_c + (grain * (1.0 / 256.0) - 0.5 / 256.0);
    }
    out_c = clamp(out_c, vec3<f32>(0.0), vec3<f32>(1.0));   // the unorm back buffer write
    return vec4<f32>(out_c * (1.0 - clamp(pp.backdrop.x, 0.0, 1.0)), 1.0);
}

// AO ORDER: UE 4.16's `ScreenSpaceAO` (ssao_ue.wgsl, binding 11) applied to the HDR scene colour right after the opaque
// scene, i.e. BEFORE fog / translucency / light shafts / SceneColorHalfRes, like UE 4.16 where SSAO only reaches the lighting (SkyLighting.usf /
// ReflectionEnvironment: the sky light's diffuse is multiplied by the AO before any post-process pass). Appended to common.wgsl + post.wgsl;
// `scene` (binding 1) is a copy of the HDR target here (a pass cannot read its own attachment).
//
// REFLECTION APPLY (docs/spec/reflection_gaps.md sections 1-2): the same pass then adds the specular indirect light the lit passes deferred (lit_common.wgsl
// LitOut, reflection.rs), exactly in ReflectionApplyPS's order (ReflectionEnvironmentShaders.usf:537-665, no reflection captures, APPLY_SKYLIGHT):
//   AO = GBufferAO * ScreenSpaceData.AmbientOcclusion; SpecularOcclusion = saturate(Square(NoV + AO) - 1 + AO)        (:561-563)
//   SpecularLighting = (0, 0, 0, 1); .rgb = SSR.rgb + .rgb * (1 - SSR.a); .a *= 1 - SSR.a                              (SSR composite)
//   .rgb *= SpecularColor (= EnvBRDF * SO); .rgb += .a * (Sky * SpecularColor * IndirectSpecularOcclusion + ExtraIndirectSpecular * SpecularColor)
// = SO * (SSR.rgb * EnvBRDF + (1 - SSR.a) * refl.rgb) with refl.rgb = the lit pass's sky term without SO. Both inputs carry the pixel's fog transmittance
// (UE fogs after ReflectionApplyPS). ScreenSpaceData.AmbientOcclusion = `ScreenSpaceAO` of the UE 4.16 SSAO passes (ssao_ue.rs / ssao_ue.wgsl), which
// already hold the distance fade, AmbientOcclusionPower and AmbientOcclusionIntensity (MainPS full-res tail).
struct ApplyU { flags: vec4<f32> }   // x SSR result valid, y SSAO on, z debug: show the SSR result alone (FN_SSR_DEBUG, reflection.rs)
@group(0) @binding(6) var refl_sky: texture_2d<f32>;    // rgb sky specular (no SO) x fog transmittance, a NoV
@group(0) @binding(7) var refl_brdf: texture_2d<f32>;   // rgb EnvBRDF x fog transmittance, a GBufferAO
@group(0) @binding(8) var ssr_tex: texture_2d<f32>;     // SSROutput (reflection.rs), rgb x RoughnessFade x Intensity, a coverage
@group(0) @binding(9) var<uniform> au: ApplyU;
@group(0) @binding(11) var screen_space_ao: texture_2d<f32>;   // UE SSAO: ScreenSpaceAO (PF_G8, full res)

fn reflections(px: vec2<i32>, screen_ao: f32) -> vec3<f32> {
    let r = textureLoad(refl_sky, px, 0);
    let b = textureLoad(refl_brdf, px, 0);
    let ao = b.a * screen_ao;
    let so = clamp((r.a + ao) * (r.a + ao) - 1.0 + ao, 0.0, 1.0);
    var ssr = vec4<f32>(0.0);
    if (au.flags.x > 0.5) { ssr = textureLoad(ssr_tex, px, 0); }
    return so * (ssr.rgb * b.rgb + (1.0 - ssr.a) * r.rgb);
}

@fragment
fn fs_ssao(in: VsOut) -> @location(0) vec4<f32> {
    let px = vec2<i32>(in.clip.xy);
    let s = textureLoad(scene, px, 0);
    // debug view: the dimmed scene + the raw SSR (the SSR reads the previous frame, so the scene must stay in the image)
    if (au.flags.z > 0.5) { let r = textureLoad(ssr_tex, px, 0); return vec4<f32>(s.rgb * 0.15 * (1.0 - r.a) + r.rgb, s.a); }
    let screen_ao = textureLoad(screen_space_ao, px, 0).r;
    if (i32(pp.view.w) == 2) { return vec4<f32>(vec3<f32>(screen_ao), s.a); }   // debug: AO only (shown raw by post.wgsl debug mode 2)
    // AO acts on the ambient (sky) light only: the HDR alpha holds the ambient share of each pixel
    let ambient_share = clamp(s.a, 0.0, 1.0);
    // FX SHADOW AO COMBINE (2026-10-05): SkyLightDiffusePS combines the sky visibility with `min(GBuffer.GBufferAO, ScreenSpaceData.AmbientOcclusion)` in BOTH
    // OcclusionCombineMode branches (UE4.16 SkyLighting.usf:83 / :88; the Athena sky light is OCM_Multiply: DFAO x min(...)). The lit passes already put
    // GBufferAO into the ambient share (lit_common.wgsl df_sky_occlusion; the AO-free OcclusionTint term is not in the share) and record it in refl_brdf.a, so the ambient share is
    // scaled by min(GBufferAO, SSAO) / GBufferAO, not by SSAO (that was GBufferAO x SSAO). No GBufferAO recorded (0: nothing lit / cleared) keeps SSAO.
    let gbuffer_ao = textureLoad(refl_brdf, px, 0).a;
    let sky_ao = select(screen_ao, min(gbuffer_ao, screen_ao) / gbuffer_ao, gbuffer_ao > 1e-4);
    return vec4<f32>(s.rgb * (1.0 - ambient_share * (1.0 - sky_ao)) + reflections(px, screen_ao), s.a);
}

// SSAO off (r.AmbientOcclusionLevels 0): ScreenSpaceData.AmbientOcclusion = 1; added with a One / One colour blend (alpha untouched), no scene copy
@fragment
fn fs_reflect(in: VsOut) -> @location(0) vec4<f32> {
    return vec4<f32>(reflections(vec2<i32>(in.clip.xy), 1.0), 0.0);
}
diagnostic(off, derivative_uniformity); 

// Shared WGSL helpers, prepended to every scene/sky shader by the Rust side (WGSL has no #include).
// Ported from FortniteRuntime/src/shaders/common.glsl + fog.glsl.
// All colour maths in the scene passes is linear; encoding to sRGB happens once, in post.wgsl.

fn decode_srgb(x: f32) -> f32 {
    if (x <= 0.04045) { return x / 12.92; }
    return pow((x + 0.055) / 1.055, 2.4);
}
fn encode_srgb(x: f32) -> f32 {
    if (x <= 0.0031308) { return x * 12.92; }
    return 1.055 * pow(x, 1.0 / 2.4) - 0.055;
}
fn to_linear(v: vec3<f32>) -> vec3<f32> { return vec3<f32>(decode_srgb(v.x), decode_srgb(v.y), decode_srgb(v.z)); }
fn to_srgb(v: vec3<f32>) -> vec3<f32> { return vec3<f32>(encode_srgb(v.x), encode_srgb(v.y), encode_srgb(v.z)); }
fn luma709(c: vec3<f32>) -> f32 { return dot(c, vec3<f32>(0.2126, 0.7152, 0.0722)); }

// Unreal-style ExponentialHeightFog: the compiled TExponentialHeightFogPS<DirectionalLightInscatteringAndVolumetricFog> of the 1.8 global shader cache
// (ported in src/fog.rs `HeightFogPs::eval`, which this mirrors line for line), evaluated per fragment. World units here are metres (GL, Y up);
// the maths runs in Unreal units (cm, Z up = renderer Y).
// TOD LIVE: the values are PER-FRAME uniform data (src/fog.rs HeightFogUniform, the live clock's ExpHeightFogValues phase blend), not baked constants: the
// including shader passes its block (lit_common.wgsl `light.fog`, sky_common.wgsl `sky.fog`). Density / falloff carry the engine /1000 remap.
struct HeightFogU {
    p0: vec4<f32>,         // x FogDensity, y FogHeightFalloff (both /1000), z FogHeight (cm), w FogMaxOpacity
    p1: vec4<f32>,         // x StartDistance (cm), y DirectionalInscatteringExponent, z DirectionalInscatteringStartDistance (cm), w View.VolumetricFogMaxDistance (cm, 0 = no volume)
    dir_color: vec4<f32>,  // rgb View.DirectionalInscatteringColor (x sun luminance), w FogCutoffDistance (cm)
    color: vec4<f32>,      // rgb FogInscatteringColor
}

// Returns (inscattered radiance rgb, transmittance a). final = scene * a + rgb. `fwd` = unit camera forward (world), used by the volumetric exclusion
// (the height fog is excluded from the first VolumetricFogMaxDistance of view depth, the volume covers it: the excluded distance along the ray is
// VolumetricFogMaxDistance / cos(angle to the view axis)).
fn height_fog(f: HeightFogU, world_m: vec3<f32>, camera_m: vec3<f32>, to_sun: vec3<f32>, fwd: vec3<f32>) -> vec4<f32> {
    let FOG_DENSITY = f.p0.x;
    let FOG_FALLOFF = f.p0.y;
    let FOG_HEIGHT_CM = f.p0.z;
    let FOG_MAX_OPACITY = f.p0.w;
    let FOG_START_DISTANCE_CM = f.p1.x;
    let FOG_DIR_EXPONENT = f.p1.y;
    let FOG_DIR_START_CM = f.p1.z;
    let FOG_VOLUME_DISTANCE_CM = f.p1.w;
    let FOG_DIR_COLOR = f.dir_color.xyz;
    let FOG_CUTOFF_DISTANCE_CM = f.dir_color.w;
    let FOG_COLOR = f.color.xyz;
    let c = (world_m - camera_m) * 100.0;
    let cam_z = camera_m.y * 100.0;
    let len = max(length(c), 1e-6);
    let along = dot(c, fwd);
    // (the select keeps 0 * inf at along == 0 from becoming NaN when there is no volume: D3D `max` returns the non-NaN operand, WGSL leaves it undefined)
    let vol_exclude = select(0.0, max(len / along * FOG_VOLUME_DISTANCE_CM, 0.0), FOG_VOLUME_DISTANCE_CM > 0.0);
    let exclude = max(vol_exclude, FOG_START_DISTANCE_CM);
    let inv_len = 1.0 / len;
    var origin_density: f32;
    var ray_len: f32;
    var dz: f32;
    if (exclude > 0.0) {
        let t = min(exclude * inv_len, 1.0);   // ExcludeIntersectionTime (saturated: a point inside the volume has no height fog left)
        let to_excl_z = c.y * t;
        origin_density = exp2(-max(FOG_FALLOFF * (cam_z + to_excl_z - FOG_HEIGHT_CM), -127.0)) * FOG_DENSITY;
        ray_len = len * (1.0 - t);
        dz = c.y - to_excl_z;
    } else {
        origin_density = FOG_DENSITY * exp2(-max(FOG_FALLOFF * (cam_z - FOG_HEIGHT_CM), -127.0));
        ray_len = len;
        dz = c.y;
    }
    // RECOVERED line integral (1 - 2^-x) / x with x = max(FogHeightFalloff * (|dz| > 0.01 ? dz : 0.01), -127)
    let x = max(FOG_FALLOFF * select(0.01, dz, abs(dz) > 0.01), -127.0);
    let line = (1.0 - exp2(-x)) * origin_density / x;
    let optical = ray_len * line;
    let dir = c * inv_len;
    let dir_gain = pow(clamp(dot(dir, to_sun), 0.0, 1.0), FOG_DIR_EXPONENT);
    let dir_factor = 1.0 - min(exp2(-(max(ray_len - FOG_DIR_START_CM, 0.0) * line)), 1.0);
    var dir_in = FOG_DIR_COLOR * (dir_gain * dir_factor);
    var trans = max(min(exp2(-optical), 1.0), 1.0 - FOG_MAX_OPACITY);
    if (FOG_CUTOFF_DISTANCE_CM > 0.0 && FOG_CUTOFF_DISTANCE_CM < len) { dir_in = vec3<f32>(0.0); trans = 1.0; }
    return vec4<f32>(FOG_COLOR * (1.0 - trans) + dir_in, trans);
}

// Fullscreen post-process: bloom, exposure, vignette, white balance, UE 4.16 filmic tonemapper, sRGB encode.
// Port of post.frag. Order follows UE4's tonemapper (bloom added to scene colour, exposure, vignette, then the colour-grading
// stage = white balance + ACES film path), every stage is an APPROXIMATION unless marked RECOVERED.
// Also contains the HDR mip downsample (bloom + exposure metering) and the exposure-adaptation compute shader.
// Common helpers (srgb) are prepended from common.wgsl.

struct PostParams {
    wb0: vec4<f32>, wb1: vec4<f32>, wb2: vec4<f32>,   // white balance matrix columns (linear sRGB -> linear sRGB)
    film_stw: vec4<f32>,       // slope, toe, shoulder
    film_clip: vec4<f32>,      // black clip, white clip
    bloom: vec4<f32>,          // intensity, threshold, enabled
    vignette: vec4<f32>,       // intensity, enabled
    ao: vec4<f32>,             // legacy block (intensity, radius m, enabled, bias): unused since the UE 4.16 SSAO (ssao_ue.rs) has its own uniform
    proj: vec4<f32>,           // tan(half fov x), tan(half fov y), near, far
    view: vec4<f32>,           // width, height, display_exponent, debug_mode
    backdrop: vec4<f32>,       // pause-menu backdrop: dim (0..1), blur (0..1)
    grade_sat: vec4<f32>,      // colour-grading saturation per region (shadows, midtones, highlights) = region * global ColorSaturation
    grade_contrast: vec4<f32>, // ColorContrast per region
    grade_gamma: vec4<f32>,    // ColorGamma per region
    grade_range: vec4<f32>,    // ColorCorrectionShadowsMax, ColorCorrectionHighlightsMin, 1 = contrast/gamma not identity, LUT output scale (1.05)
    // SCALABILITY: x = r.Tonemapper.Sharpen / 6 (TonemapperParams.y, PostProcessTonemap.cpp:950-953), y = 1: grain quantization
    // (r.Tonemapper.GrainQuantization > 0, PostProcessTonemap.cpp:609-617), zw = GrainRandomFull.xy (GrainRandomFromFrame, PostProcessTonemap.h:34-38)
    tonemap_ext: vec4<f32>,
    // POSTFX SETTINGS (effect_settings.rs): scene colour fringe, xy = FringeUVParams (.x scales the G sample position, .y the R one about the view
    // centre), z = 1 when USE_COLOR_FRINGE (SceneFringeIntensity > 0.01 after r.SceneColorFringeQuality, PostProcessTonemap.cpp:620)
    fringe: vec4<f32>,
    scene_tint: vec4<f32>,
}
struct ExposureState { ev: f32, target_ev: f32, exposure: f32, avg_luminance: f32 }

@group(0) @binding(0) var<uniform> pp: PostParams;
@group(0) @binding(1) var scene: texture_2d<f32>;
@group(0) @binding(2) var depth_tex: texture_depth_2d;
@group(0) @binding(3) var<storage, read> exposure_state: ExposureState;
@group(0) @binding(4) var lin_samp: sampler;
// BLOOM HOOK: the bloom image of fn_postfx::bloom (UE 4.16 chain: SceneColorHalfRes -> 5 downsamples -> Bloom6..1 Gaussians, tint / 6),
// half resolution, NOT exposed, NOT multiplied by BloomIntensity (PostprocessInput1 of FPostProcessTonemapPS).
@group(0) @binding(5) var bloom_tex: texture_2d<f32>;
// COLOR LUT (GLOBAL LOOK): the 32^3 colour-grading LUT of FCombineLUTs (color_lut.rs / color_lut.wgsl, rebuilt every frame from `pp`), = OutDeviceColor / 1.05
// rounded to 10 bits. Binding 10 because ssao_apply.wgsl (which also includes this file) owns 6..9.
@group(0) @binding(10) var color_lut: texture_3d<f32>;

struct VsOut { @builtin(position) clip: vec4<f32>, @location(0) uv: vec2<f32> }   // uv: GL convention (y up)

@vertex
fn vs_main(@builtin(vertex_index) i: u32) -> VsOut {
    var o: VsOut;
    let x = f32(i32(i & 1u) * 4 - 1);
    let y = f32(i32((i >> 1u) & 1u) * 4 - 1);
    // full-screen triangle: (-1,-1), (3,-1), (-1,3)
    o.clip = vec4<f32>(x, y, 0.0, 1.0);
    o.uv = vec2<f32>(x, y) * 0.5 + 0.5;
    return o;
}

fn tc(p: vec2<f32>) -> vec2<f32> { return vec2<f32>(p.x, 1.0 - p.y); }   // GL uv -> texture coordinate

// ---- AO: the screen-space AO is UE 4.16's (ssao_ue.rs / ssao_ue.wgsl), applied by ssao_apply.wgsl before fog / translucency ----

// ---- Bloom (BLOOM HOOK): the chain runs in fn_postfx::bloom; the tonemapper only samples it (bilinear, screen uv) and scales it by
// ColorScale1 = BloomIntensity (+ BloomDirtMask tint * mask; the Athena volumes set no BloomDirtMask texture -> BlackDummy -> 0). ----
fn bloom_color(uv: vec2<f32>) -> vec3<f32> {
    return textureSampleLevel(bloom_tex, lin_samp, tc(uv), 0.0).rgb * pp.bloom.x;
}

// ---- Filmic tonemapper curve (UE4 FilmToneMap structure: log-domain toe/straight/shoulder blend) ----
fn film_curve(untonemapped: vec3<f32>) -> vec3<f32> {
    let slope = pp.film_stw.x;
    let toe = pp.film_stw.y;
    let shoulder = pp.film_stw.z;
    let black = pp.film_clip.x;
    let white = pp.film_clip.y;
    let toe_scale = 1.0 + black - toe;
    let shoulder_scale = 1.0 + white - shoulder;
    let in_match = 0.18;
    let out_match = 0.18;
    var toe_match: f32;
    if (toe > 0.8) { toe_match = (1.0 - toe - out_match) / slope + log(in_match) / 2.302585093; }
    else {
        let bt = (out_match + black) / toe_scale - 1.0;
        toe_match = log(in_match) / 2.302585093 - 0.5 * log((1.0 + bt) / (1.0 - bt)) * (toe_scale / slope);
    }
    let straight_match = (1.0 - toe) / slope - toe_match;
    let shoulder_match = shoulder / slope - straight_match;
    let log_color = log(max(untonemapped, vec3<f32>(1e-10))) / 2.302585093;
    let straight = slope * (log_color + straight_match);
    var toe_color = -black + 2.0 * toe_scale / (1.0 + exp(-2.0 * (slope / toe_scale) * (log_color - toe_match)));
    var shoulder_color = (1.0 + white) - 2.0 * shoulder_scale / (1.0 + exp(2.0 * (slope / shoulder_scale) * (log_color - shoulder_match)));
    toe_color = select(straight, toe_color, log_color < vec3<f32>(toe_match));
    shoulder_color = select(straight, shoulder_color, log_color > vec3<f32>(shoulder_match));
    var t = clamp((log_color - toe_match) / (shoulder_match - toe_match), vec3<f32>(0.0), vec3<f32>(1.0));
    if (shoulder_match < toe_match) { t = 1.0 - t; }
    t = (3.0 - 2.0 * t) * t * t;
    return mix(toe_color, shoulder_color, t);
}
// ACES matrices exactly as compiled into the UE 4.16 CombineLUTs shader (WGSL mat3x3 is column-major, so each constructor lists
// the transposed rows of the HLSL dp3 constants). They include the D65 <-> D60 adaptation.
const SRGB_TO_AP0 = mat3x3<f32>(0.439701, 0.089792, 0.017544, 0.382978, 0.813423, 0.111544, 0.177335, 0.096762, 0.870704);
const AP0_TO_AP1 = mat3x3<f32>(1.451439, -0.076554, 0.008316, -0.236511, 1.176230, -0.006032, -0.214929, -0.099676, 0.997716);
const AP1_TO_SRGB = mat3x3<f32>(1.705052, -0.130257, -0.024003, -0.621791, 1.140803, -0.128969, -0.083258, -0.010549, 1.152972);
const AP1_LUMA = vec3<f32>(0.2722287168, 0.6740817658, 0.0536895174);
const RRT_SAT_FACTOR: f32 = 0.96;   // RECOVERED: 0.96 / 0.93 are literals in the 4.16 film path
const ODT_SAT_FACTOR: f32 = 0.93;
// LUT domain: LogToLin(0) .. LogToLin(1), LogToLin(x) = 0.18 * 2^((x - 0.434018) * 14). RECOVERED.
const LUT_MIN: f32 = 0.0026677086;
const LUT_MAX: f32 = 43.707738;

// CombineLUTs colour correction, RECOVERED from the 4.16 CombineLUTs DXBC (shader 1182809): sRGB -> AP1, AP1 luma, shadows / midtones /
// highlights regions (weights 1 - smoothstep(luma / ShadowsMax), smoothstep((luma - HighlightsMin) / (1 - HighlightsMin)), remainder),
// each max(luma + sat * (c - luma), 0). ColorSaturationShadows = Midtones = 1.25 (TODM_A), Highlights 1.0, ShadowsMax 0.09 and
// HighlightsMin 0.5 (exe ctor defaults); contrast/gamma/gain/offset stay identity. Mirrors tonemap::color_grade.
const SRGB_TO_AP1 = mat3x3<f32>(0.613191, 0.070207, 0.020619, 0.339512, 0.916336, 0.109567, 0.047366, 0.013450, 0.869607);
fn grade_region(ap1: vec3<f32>, luma: f32, sat: f32, contrast: f32, gamma: f32) -> vec3<f32> {
    var w = max(vec3<f32>(luma) + (ap1 - vec3<f32>(luma)) * sat, vec3<f32>(0.0));
    if (pp.grade_range.z > 0.5) {
        w = pow(w * (1.0 / 0.18), vec3<f32>(contrast)) * 0.18;
        w = pow(w, vec3<f32>(1.0 / gamma));
    }
    return w;
}
// ColorCorrectAll of the 4.16 CombineLUTs: three regions with their own saturation / contrast / gamma (gain 1, offset 0 in every phase).
// Per-phase values come from tonemap::PostSettings (Evening = sunset: shadows 1.5, midtones 1.15).
fn color_grade(c: vec3<f32>) -> vec3<f32> {
    let ap1 = SRGB_TO_AP1 * c;
    let luma = dot(ap1, AP1_LUMA);
    let xs = clamp(luma / pp.grade_range.x, 0.0, 1.0);
    let xh = clamp((luma - pp.grade_range.y) / (1.0 - pp.grade_range.y), 0.0, 1.0);
    let sw = 1.0 - xs * xs * (3.0 - 2.0 * xs);
    let hw = xh * xh * (3.0 - 2.0 * xh);
    let mw = 1.0 - sw - hw;
    let shadows = grade_region(ap1, luma, pp.grade_sat.x, pp.grade_contrast.x, pp.grade_gamma.x);
    let mids = grade_region(ap1, luma, pp.grade_sat.y, pp.grade_contrast.y, pp.grade_gamma.y);
    let highs = grade_region(ap1, luma, pp.grade_sat.z, pp.grade_contrast.z, pp.grade_gamma.z);
    return AP1_TO_SRGB * (shadows * sw + mids * mw + highs * hw);
}
// ACES RRT hue-dependent red modifier (RECOVERED, 4.16): pivot 0.03, scale 0.82, hue 0, width 135.
fn aces_red_modifier(aces_in: vec3<f32>) -> vec3<f32> {
    var aces = aces_in;
    let minrgb = min(aces.r, min(aces.g, aces.b));
    let maxrgb = max(aces.r, max(aces.g, aces.b));
    let saturation = (max(maxrgb, 1e-10) - max(minrgb, 1e-10)) / max(maxrgb, 1e-2);
    var hue = 0.0;
    if (!(aces.r == aces.g && aces.g == aces.b)) {
        hue = degrees(atan2(1.7320508 * (aces.g - aces.b), 2.0 * aces.r - aces.g - aces.b));
        if (hue < 0.0) { hue = hue + 360.0; }
    }
    let centered = select(hue, hue - 360.0, hue > 180.0);
    let w = smoothstep(0.0, 1.0, 1.0 - abs(2.0 * centered / 135.0));
    aces.r = aces.r + w * w * saturation * (0.03 - aces.r) * (1.0 - 0.82);
    return aces;
}
// COLOR LUT (GLOBAL LOOK): CombineLUTsCommon of the 1.8 DXBC (GlobalShaderCache#1182809) for one LUT-domain linear colour, up to OutDeviceColor (the
// caller stores it / 1.05): WhiteBalance, ColorGrade (ColorCorrectAll in AP1), FilmToneMap (sRGB -> AP0, ACES red modifier, AP0 -> AP1 clamped, RRT sat
// 0.96, Film* curve, ODT sat 0.93), AP1 -> sRGB clamped, ColorCorrection (MappingPolynomial: r.Color.Min/Mid/Max not in the cooked ini -> 0 / 0.5 / 1 =
// identity), lerp(FilmColor * ColorScale, OverlayColor, a) (no fade: identity), pow(max(0, x), InverseGamma.y) (y = 2.2 / DisplayGamma = view.z),
// LinearToSrgb (OutputDevice 0: r.HDR.Display.OutputDevice 0 and r.TonemapperGamma 0 are not in the cooked ini).
fn lut_device_color(linear: vec3<f32>) -> vec3<f32> {
    let wb = mat3x3<f32>(pp.wb0.xyz, pp.wb1.xyz, pp.wb2.xyz);
    let graded = color_grade(wb * linear);
    var ap0 = SRGB_TO_AP0 * graded;
    ap0 = aces_red_modifier(ap0);
    var ap1 = max(AP0_TO_AP1 * ap0, vec3<f32>(0.0));
    ap1 = mix(vec3<f32>(dot(ap1, AP1_LUMA)), ap1, RRT_SAT_FACTOR);
    var toned = film_curve(ap1);
    toned = max(mix(vec3<f32>(dot(toned, AP1_LUMA)), toned, ODT_SAT_FACTOR), vec3<f32>(0.0));
    let film = max(AP1_TO_SRGB * toned, vec3<f32>(0.0));
    return to_srgb(pow(film, vec3<f32>(pp.view.z)));
}
// ColorLookupTable (PostProcessTonemap.usf:68, 1.8 DXBC FPostProcessTonemapPS0 #1070630): LUTEncodedColor = LinToLog(c) = saturate(log2(c) / 14 + 0.610727)
// (no `+ LogToLin(0)` in the 1.8 build), UVW = enc * 31/32 + 0.5/32, trilinear clamp sample, * 1.05. log2 of 0 / negative (NaN) saturates to 0 like D3D.
fn color_lookup_table(c: vec3<f32>) -> vec3<f32> {
    let enc = clamp(log2(max(c, vec3<f32>(0.0))) * (1.0 / 14.0) + vec3<f32>(0.610727), vec3<f32>(0.0), vec3<f32>(1.0));
    let uvw = enc * (31.0 / 32.0) + vec3<f32>(0.5 / 32.0);
    return textureSampleLevel(color_lut, lin_samp, uvw, 0.0).rgb * 1.05;
}
// UE ComputeVignetteMask, RECOVERED from the 4.16 tonemap VS/PS: natural cos^4 vignette, circle-space position normalised so the
// screen corner sits at radius sqrt(2) for every aspect: p = sqrt2/sqrt(1+a^2) * (ndc.x, a*ndc.y), a = height/width; mask = 1/(1+|p I|^2)^2.
fn vignette_mask(uv: vec2<f32>) -> f32 {
    let a = pp.view.y / pp.view.x;
    let p = (uv * 2.0 - 1.0) * vec2<f32>(1.0, a) * (1.4142135624 / sqrt(1.0 + a * a)) * pp.vignette.x;
    let t = 1.0 / (1.0 + dot(p, p));
    return t * t;
}

// Pause-menu backdrop blur: trilinear taps of the HDR mip chain (box-filtered), 3x3 kernel at lod = blur * 5.
fn blurred_scene(uv: vec2<f32>) -> vec4<f32> {
    let lod = clamp(pp.backdrop.y, 0.0, 1.0) * 5.0;
    let texel = 1.0 / vec2<f32>(textureDimensions(scene, i32(floor(lod))));
    var acc = vec4<f32>(0.0);
    var wsum = 0.0;
    for (var y = -1; y <= 1; y = y + 1) {
        for (var x = -1; x <= 1; x = x + 1) {
            let w = select(1.0, 2.0, x == 0) * select(1.0, 2.0, y == 0);
            acc = acc + textureSampleLevel(scene, lin_samp, tc(uv + vec2<f32>(f32(x), f32(y)) * texel * 1.5), lod) * w;
            wsum = wsum + w;
        }
    }
    return acc / wsum;
}

@fragment
fn fs_main(in: VsOut) -> @location(0) vec4<f32> {
    let uv = in.uv;
    let debug_mode = i32(pp.view.w);
    let exposure = exposure_state.exposure;
    var scene_sample = textureSampleLevel(scene, lin_samp, tc(uv), 0.0);
    // USE_COLOR_FRINGE (PostProcessTonemap.usf:155-159 / :332-341): FringeUV = ScreenPosToUV(ScreenPos * FringeUVParams.{r,g}); R from FringeUV.zw (scale
    // .g = 1/(1+Offset*ScaleR)), G from FringeUV.xy (scale .r), B from the unshifted UV (bilinear clamp sampler, no grain jitter: GrainJitter 0)
    if (pp.fringe.z > 0.5) {
        let sp = uv * 2.0 - 1.0;
        scene_sample.r = textureSampleLevel(scene, lin_samp, tc(sp * pp.fringe.y * 0.5 + 0.5), 0.0).r;
        scene_sample.g = textureSampleLevel(scene, lin_samp, tc(sp * pp.fringe.x * 0.5 + 0.5), 0.0).g;
    }
    let blurred = pp.backdrop.y > 0.0;
    if (blurred) { scene_sample = blurred_scene(uv); }
    var c = scene_sample.rgb;
    // USE_SHARPEN (PostProcessTonemap.usf:357-412): Luminance (0.3, 0.59, 0.11) of the centre and of 4 neighbours (-1,0) (1,0) (-1,-1) (-1,1),
    // EdgeMask = saturate(1 - ExposureScale * max|A0 - L|), SceneColor += ((C1 + C2 + C3 + C4) - 4 SceneColor) * (-EdgeMask * Sharpen / 6)
    if (pp.tonemap_ext.x > 0.0 && !blurred) {
        let texel = 1.0 / pp.view.xy;
        let c1 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(-1.0, 0.0) * texel, 0.0).rgb;
        let c2 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(1.0, 0.0) * texel, 0.0).rgb;
        let c3 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(-1.0, -1.0) * texel, 0.0).rgb;
        let c4 = textureSampleLevel(scene, lin_samp, tc(uv) + vec2<f32>(-1.0, 1.0) * texel, 0.0).rgb;
        let lw = vec3<f32>(0.3, 0.59, 0.11);
        let a0 = dot(c, lw);
        let ln = vec4<f32>(dot(c1, lw), dot(c2, lw), dot(c3, lw), dot(c4, lw));
        let d = abs(vec4<f32>(a0) - ln);
        let hdr_edge = exposure_state.exposure * max(max(d.x, d.y), max(d.z, d.w));
        let edge_mask = clamp(1.0 - hdr_edge, 0.0, 1.0);
        let lerp_factor = -edge_mask * pp.tonemap_ext.x;
        c = c + ((c1 + c2 + c3 + c4) - c * 4.0) * lerp_factor;
    }
    // AO ORDER: the screen-space AO is no longer applied here; ssao_apply.wgsl (ssao_pass.rs) applies it to the HDR scene right after the opaque
    // scene, before fog / translucency / bloom / the histogram, matching UE 4.16 where SSAO only acts inside the lighting.
    let raw_scene = scene_sample.rgb;
    var bloom = vec3<f32>(0.0);
    if (pp.bloom.z > 0.5 && !blurred) { bloom = bloom_color(uv); }
    // PostProcessTonemap.usf: LinearColor = SceneColor * ColorScale0 + CombinedBloom * ColorScale1; LinearColor *= ExposureScale
    c = (c * pp.scene_tint.rgb + bloom) * exposure;
    if (pp.vignette.y > 0.5) { c = c * vignette_mask(uv); }
    if (debug_mode == 5) { return vec4<f32>(vec3<f32>(vignette_mask(uv)), 1.0); }
    if (debug_mode == 2) { return vec4<f32>(clamp(raw_scene, vec3<f32>(0.0), vec3<f32>(1.0)), 1.0); }   // the AO pass wrote the raw AO term in this mode
    if (debug_mode == 3) { return vec4<f32>(to_srgb(clamp(bloom * 4.0, vec3<f32>(0.0), vec3<f32>(1.0))), 1.0); }
    if (debug_mode == 4) { return vec4<f32>(to_srgb(clamp(c, vec3<f32>(0.0), vec3<f32>(1.0))), 1.0); }
    // The tonemap pass samples the 32^3 colour-grading LUT with saturate(log2(c)/14 + 0.610727): input clamped to the LUT domain
    // before white balance (RECOVERED). Direct evaluation replaces the trilinear 32^3 interpolation; the grain dither is applied below when the level enables it.
    if (debug_mode == 1) {
        let wb = mat3x3<f32>(pp.wb0.xyz, pp.wb1.xyz, pp.wb2.xyz);
        return vec4<f32>(to_srgb(clamp(color_grade(wb * clamp(c, vec3<f32>(LUT_MIN), vec3<f32>(LUT_MAX))), vec3<f32>(0.0), vec3<f32>(1.0))), 1.0);
    }
    // COLOR LUT (GLOBAL LOOK): the colour transform (white balance, grading, ACES film path, display gamma, sRGB) comes from the 32^3 LUT that
    // color_lut.wgsl bakes from the same `pp` block (OutDeviceColor / 1.05, 10-bit), sampled trilinearly and * 1.05 (ColorLookupTable). The old direct
    // evaluation lacked CombineLUTs' / 1.05 and came out 5 % brighter (mid grey 123 instead of 117 / 255, highlights clipped at 0.952).
    var out_c = color_lookup_table(c);
    // USE_GRAIN_QUANTIZATION (PostProcessTonemap.usf:474-481): Grain = frac(sin(GrainUV.x + GrainUV.y * 543.31) * 493013) with GrainUV = TexCoord +
    // GrainRandomFull.xy; OutDeviceColor += Grain / 256 - 0.5 / 256 (after the LUT, before the 8-bit write: DXBC `mad r0.xyz, lut, 1.05, grain`)
    if (pp.tonemap_ext.y > 0.5) {
        let guv = tc(uv) + pp.tonemap_ext.zw;
        let grain = fract(sin(guv.x + guv.y * 543.31) * 493013.0);
        out_c = out_c + (grain * (1.0 / 256.0) - 0.5 / 256.0);
    }
    out_c = clamp(out_c, vec3<f32>(0.0), vec3<f32>(1.0));   // the unorm back buffer write
    return vec4<f32>(out_c * (1.0 - clamp(pp.backdrop.x, 0.0, 1.0)), 1.0);
}

// COLOR LUT (GLOBAL LOOK 2026-10-05): FCombineLUTs, the volume colour-grading LUT the UE 4.16 tonemapper samples. Appended after common.wgsl + post.wgsl
// (`lut_device_color` and the PostParams block `pp` live in post.wgsl; this module only uses `pp`, binding 0 of group 0).
// 1.8 DXBC of the global shader cache (GlobalShaderCache#1182809, the USE_VOLUME_LUT pixel shader writing one slice per SV_RenderTargetArrayIndex):
//   Neutral = (UV - 0.5/32) * 32/31 (layer / 31)          `add v0.xy, -0.015625` + `mul 1.032258`, `mul r1.z, layer, 0.032258`
//   LinearColor = LogToLin(Neutral) = 0.18 * 2^((Neutral - 0.434018) * 14)   (NO `- LogToLin(0)` in the 1.8 build, unlike the 4.16 source)
//   ... white balance, colour grade, film tone map, AP1 -> sRGB, MappingPolynomial, ColorScale / Overlay, pow(InverseGamma.y), LinearToSrgb ...
//   OutColor.rgb = OutDeviceColor / 1.05                    `mul o0.xyz, r0.xyzx, l(0.952381)`
// into a 32^3 PF_A2B10G10R10 (PostProcessCombineLUTs.cpp:1022) render target: the unorm write saturates and rounds to 10 bits. The tonemapper samples it
// bilinearly (clamp) at saturate(log2(c) / 14 + 0.610727) * 31/32 + 0.5/32 and multiplies by 1.05 (post.wgsl).
// The texture here is rgba16float (storage-writable in core WebGPU); the 10-bit unorm rounding is applied explicitly before the store.
@group(1) @binding(0) var lut_out: texture_storage_3d<rgba16float, write>;

@compute @workgroup_size(4, 4, 4)
fn combine_luts(@builtin(global_invocation_id) id: vec3<u32>) {
    if (any(id >= vec3<u32>(32u))) { return; }
    let neutral = vec3<f32>(id) / 31.0;
    let linear = exp2((neutral - vec3<f32>(0.434018)) * 14.0) * 0.18;
    let stored = clamp(lut_device_color(linear) * (1.0 / 1.05), vec3<f32>(0.0), vec3<f32>(1.0));
    textureStore(lut_out, vec3<i32>(id), vec4<f32>(round(stored * 1023.0) / 1023.0, 0.0));
}
diagnostic(off, derivative_uniformity); // REFLECTION APPLY (SSR): the hierarchical Z buffer of UE 4.16 (`BuildHZB`, SceneOcclusion.cpp:1076; `HZBBuildPS`, HZBOcclusion.usf:12), PF_R16F, the
// FURTHEST depth of every 2x2 block. UE stores its device Z (reversed, infinite far: Z = near / ViewDepth, 0 = sky) and keeps the MIN; this renderer's depth
// is 0 = near / 1 = far, so mip 0 converts every pixel to UE's device Z (near 10 cm, metres here: 0.1 / w) and keeps the min the same way.
// Mip 0 (STAGE 0): texel (i, j) of the HZBSize = 2^NumMips chain covers buffer pixels 2i..2i+1, 2j..2j+1 (InputUvFactorAndOffset = 2 HZBSize / BufferSize,
// four point taps at +-0.25 buffer texel), clamped to the viewport (InputViewportMaxBound); mips 1..: the 2x2 texels of the previous mip, clamped to it.
struct HzbU { depth: vec4<f32> }   // x port near (m), y port far (m), z UE near (m) of the device Z
@group(0) @binding(0) var<uniform> hu: HzbU;
@group(0) @binding(1) var depth_tex: texture_depth_2d;
@group(0) @binding(2) var src_tex: texture_2d<f32>;

@vertex
fn vs_main(@builtin(vertex_index) i: u32) -> @builtin(position) vec4<f32> {
    let x = f32(i32(i & 1u) * 4 - 1);
    let y = f32(i32((i >> 1u) & 1u) * 4 - 1);
    return vec4<f32>(x, y, 0.0, 1.0);
}

// UE device Z of a port depth sample: near / ViewDepth; the cleared depth (1 = nothing drawn) is UE's far plane at infinity, 0
fn ue_device_z(d: f32) -> f32 {
    if (d >= 1.0) { return 0.0; }
    let n = hu.depth.x;
    let f = hu.depth.y;
    let w = n * f / (f - d * (f - n));
    return hu.depth.z / w;
}

@fragment
fn fs_mip0(@builtin(position) frag: vec4<f32>) -> @location(0) vec4<f32> {
    let size = vec2<i32>(textureDimensions(depth_tex));
    let p = vec2<i32>(floor(frag.xy)) * 2;
    let m = size - vec2<i32>(1);
    let a = ue_device_z(textureLoad(depth_tex, min(p, m), 0));
    let b = ue_device_z(textureLoad(depth_tex, min(p + vec2<i32>(1, 0), m), 0));
    let c = ue_device_z(textureLoad(depth_tex, min(p + vec2<i32>(0, 1), m), 0));
    let d = ue_device_z(textureLoad(depth_tex, min(p + vec2<i32>(1, 1), m), 0));
    return vec4<f32>(min(min(a, b), min(c, d)));
}

@fragment
fn fs_down(@builtin(position) frag: vec4<f32>) -> @location(0) vec4<f32> {
    let m = vec2<i32>(textureDimensions(src_tex)) - vec2<i32>(1);
    let p = vec2<i32>(floor(frag.xy)) * 2;
    let a = textureLoad(src_tex, min(p, m), 0).r;
    let b = textureLoad(src_tex, min(p + vec2<i32>(1, 0), m), 0).r;
    let c = textureLoad(src_tex, min(p + vec2<i32>(0, 1), m), 0).r;
    let d = textureLoad(src_tex, min(p + vec2<i32>(1, 1), m), 0).r;
    return vec4<f32>(min(min(a, b), min(c, d)));
}
diagnostic(off, derivative_uniformity); // REFLECTION APPLY (SSR): port of UE 4.16 screen space reflections (ScreenSpaceReflections.usf `ScreenSpaceReflectionsPS`, ScreenSpaceRayCast.usf `RayCast`,
// `ReprojectHit`, `SampleScreenColor`) and of `SSRTemporalAAPS` (PostProcessTemporalAA.usf:260 + PostProcessTemporalCommon.usf) for views without temporal AA.
// See reflection.rs for the parameters (r.SSR.Quality, the post-process SSR settings, ComputeSSRQuality / ComputeSSRParams).
//
// Port conventions: the GBuffer is the lit passes' reflection target 2 (xyz world normal, w roughness, xyz = 0 for ShadingModelID 0); the scene depth is
// this renderer's (0 = near, 1 = far); the ray maths run in UE's view space (x right, y up, z = view depth) with UE's reversed infinite projection
// (screen z = near / view depth), so the HZB (hzb.wgsl), the compare tolerance and the hit refinement are UE's numbers. ClipToPrevClip is this renderer's
// (port clip space, no-AA matrices, as taa.wgsl): a hit's UE device Z is turned back into this renderer's depth before the reprojection.
struct SsrU {
    view: mat4x4<f32>,          // world -> view (renderer: -z forward)
    clip_to_prev: mat4x4<f32>,  // View.ClipToPrevClip (renderer clip space, no-AA matrices)
    proj: vec4<f32>,            // ViewToClip: x P[0][0], y P[1][1], zw TAA jitter (NDC) added to the screen position
    params: vec4<f32>,          // SSRParams.x intensity, .y RoughnessMaskScale, z View.StateFrameIndexMod8, w NumSteps
    hzb: vec4<f32>,             // HZBUvFactorAndInvFactor
    viewport: vec4<f32>,        // w, h, 1 / w, 1 / h
    depth: vec4<f32>,           // x port near (m), y port far (m), z UE near (m) of the device Z, w flags (1 = velocity texture, 2 = debug: trace as roughness 0)
}
@group(0) @binding(0) var<uniform> su: SsrU;
@group(0) @binding(1) var depth_tex: texture_depth_2d;
@group(0) @binding(2) var gbuf: texture_2d<f32>;
@group(0) @binding(3) var hzb_tex: texture_2d<f32>;
@group(0) @binding(4) var point_samp: sampler;
@group(0) @binding(5) var color_tex: texture_2d<f32>;
@group(0) @binding(6) var velocity_tex: texture_2d<f32>;

@vertex
fn vs_main(@builtin(vertex_index) i: u32) -> @builtin(position) vec4<f32> {
    let x = f32(i32(i & 1u) * 4 - 1);
    let y = f32(i32((i >> 1u) & 1u) * 4 - 1);
    return vec4<f32>(x, y, 0.0, 1.0);
}

fn is_nan_or_inf(x: f32) -> bool { return x != x || abs(x) > 3.0e38; }
// HLSL saturate(a / b) including its NaN -> 0 / inf -> 1 behaviour
fn saturate_div(a: f32, b: f32) -> f32 {
    if (b == 0.0) { return select(0.0, 1.0, a > 0.0); }
    return clamp(a / b, 0.0, 1.0);
}
fn viewport_px(uv: vec2<f32>) -> vec2<i32> { return clamp(vec2<i32>(floor(uv * su.viewport.xy)), vec2<i32>(0), vec2<i32>(su.viewport.xy) - vec2<i32>(1)); }

// InterleavedGradientNoise (Random.usf:27)
fn interleaved_gradient_noise(uv_in: vec2<f32>, frame_id: f32) -> f32 {
    let uv = uv_in + frame_id * (vec2<f32>(47.0, 17.0) * 0.695);
    return fract(52.9829189 * fract(dot(uv, vec2<f32>(0.06711056, 0.00583715))));
}
// View.ViewToClip of a UE view-space point (w = 1) or direction (w = 0): clip.xy = P xy + jitter * z, clip.z = near * w, clip.w = z
fn view_to_clip(p: vec3<f32>, w: f32) -> vec4<f32> {
    return vec4<f32>(p.x * su.proj.x + su.proj.z * p.z, p.y * su.proj.y + su.proj.w * p.z, su.depth.z * w, p.z);
}

// RayCast (ScreenSpaceRayCast.usf:40) with USE_HZB 1, SCALAR_BRANCHLESS 0, VECTORIZED_BRANCHLESS 0: the first `#elif 1` loop (:197), 4 HZB taps per iteration.
// Returns (hit screen position xy, hit UE device Z, time: 0.5 = hit, 1 = miss).
fn ray_cast(start_v: vec3<f32>, dir: vec3<f32>, roughness: f32, scene_depth: f32, num_steps: i32, step_offset: f32) -> vec4<f32> {
    let ray_dir_v = dir * scene_depth;
    let end_v = start_v + ray_dir_v;
    let start_clip = view_to_clip(start_v, 1.0);
    let end_clip = view_to_clip(end_v, 1.0);
    let start_s = start_clip.xyz / start_clip.w;
    let end_s = end_clip.xyz / end_clip.w;
    let depth_clip = start_clip + view_to_clip(vec3<f32>(0.0, 0.0, scene_depth), 0.0);
    let depth_s = depth_clip.xyz / depth_clip.w;
    var step_s = end_s - start_s;
    {
        // clip the step to the viewport
        let inv_factor = 0.5 * length(step_s.xy);
        let abs_step = abs(step_s.xy);
        let s = (abs_step - max(abs(step_s.xy + start_s.xy * inv_factor) - inv_factor, vec2<f32>(0.0))) / abs_step;
        step_s = step_s * (min(s.x, s.y) / inv_factor);
    }
    let start_uvz = vec3<f32>((start_s.xy * vec2<f32>(0.5, -0.5) + 0.5) * su.hzb.xy, start_s.z);
    var step_uvz = vec3<f32>(step_s.xy * vec2<f32>(0.5, -0.5) * su.hzb.xy, step_s.z);
    let step = 1.0 / f32(num_steps);
    let tolerance = max(abs(step_uvz.z), (start_s.z - depth_s.z) * 4.0) * step;
    var result = vec4<f32>(0.0, 0.0, 0.0, 1.0);
    var last_diff = 0.0;
    var level = 1.0;   // HZB_LEVEL_OFFSET
    step_uvz = step_uvz * step;
    var ray = start_uvz + step_uvz * step_offset;
    if (any(step_uvz != step_uvz) || any(ray != ray)) { return result; }   // degenerate step (NaN): no taps can hit
    for (var i = 0; i < num_steps; i = i + 4) {
        let uv0 = ray.xyxy + step_uvz.xyxy * vec4<f32>(1.0, 1.0, 2.0, 2.0);
        let uv1 = ray.xyxy + step_uvz.xyxy * vec4<f32>(3.0, 3.0, 4.0, 4.0);
        let sample_z = ray.zzzz + step_uvz.zzzz * vec4<f32>(1.0, 2.0, 3.0, 4.0);
        let sample_depth = vec4<f32>(
            textureSampleLevel(hzb_tex, point_samp, uv0.xy, level).r, textureSampleLevel(hzb_tex, point_samp, uv0.zw, level).r,
            textureSampleLevel(hzb_tex, point_samp, uv1.xy, level).r, textureSampleLevel(hzb_tex, point_samp, uv1.zw, level).r);
        let diff = sample_z - sample_depth;
        let hit = abs(-diff - vec4<f32>(tolerance)) < vec4<f32>(tolerance);
        if (any(hit)) {
            var d0 = diff.z;
            var d1 = diff.w;
            var min_time = 3.0;
            if (hit.z) { d0 = diff.y; d1 = diff.z; min_time = 2.0; }
            if (hit.y) { d0 = diff.x; d1 = diff.y; min_time = 1.0; }
            if (hit.x) { d0 = last_diff; d1 = diff.x; min_time = 0.0; }
            let time_lerp = saturate_div(d0, d0 - d1);
            result = vec4<f32>(ray + step_uvz * (min_time + time_lerp), 0.5);
