// PostProcessTemporalCommon.usf with AA_ALPHA 1, AA_CROSS 0, AA_DYNAMIC 1, AA_LERP 8, AA_NAN 1 and the defaults AA_AABB 1, AA_FILTERED 1, AA_ROUND 1, AA_TONE 1,
