    let t_neg = (box_ - org) * rcp_dir;
    let t_pos = (-box_ - org) * rcp_dir;
    return max(max(min(t_neg.x, t_pos.x), min(t_neg.y, t_pos.y)), min(t_neg.z, t_pos.z));
