// conventions): the AO passes then normalize a finite vector exactly as UE does instead of normalize(0) = NaN.
fn gbuffer_normal(uv: vec2<f32>) -> vec3<f32> {
    let n = textureLoad(gbuf_tex, texel_of(uv, u.buffer_size.xy), 0).xyz;
    return select(n, vec3<f32>(-1.0), all(n == vec3<f32>(0.0)));
}
// ConvertFromDeviceZ of the HZB (UE reversed infinite projection: SceneDepth = Near / DeviceZ)
fn convert_from_device_z(device_z: f32) -> f32 { return u.depth.z / max(device_z, 1.0e-10); }
fn to_ue_view(n: vec3<f32>) -> vec3<f32> { return vec3<f32>(dot(u.to_view0.xyz, n), dot(u.to_view1.xyz, n), dot(u.to_view2.xyz, n)); }

// 0: not similar .. 1: very similar
fn compute_depth_similarity(a: f32, b: f32, tweak_scale: f32) -> f32 { return clamp(1.0 - abs(a - b) * tweak_scale, 0.0, 1.0); }

// ---- MainSetupPS: downsample depth + normal for the lower resolution passes ----
@fragment
fn fs_setup(in: VsOut) -> @location(0) vec4<f32> {
    let in_uv = in.pos.xy * u.out_size.zw;
    // INITIAL_PASS: PostprocessInput0Size (the scene), else PostprocessInput1Size (the previous setup)
    let pixel = select(u.in1_size.zw, u.in0_size.zw, INITIAL_PASS);
    var uvs = array<vec2<f32>, 4>(in_uv + vec2<f32>(-0.5, -0.5) * pixel, in_uv + vec2<f32>(0.5, -0.5) * pixel,
                                  in_uv + vec2<f32>(-0.5, 0.5) * pixel, in_uv + vec2<f32>(0.5, 0.5) * pixel);
    var samples: array<vec4<f32>, 4>;
    for (var i = 0u; i < 4u; i = i + 1u) {
        samples[i] = vec4<f32>(normalize(gbuffer_normal(uvs[i])) * 0.5 + 0.5, calc_scene_depth(uvs[i])); // GetGBufferData(UV[i], true): normalized (usf:239)
    }
    let max_z = max(max(samples[0].a, samples[1].a), max(samples[2].a, samples[3].a));
    var avg = vec4<f32>(0.0001);
    let inv_threshold = u.setup.y;
    for (var i = 0u; i < 4u; i = i + 1u) {
        avg = avg + vec4<f32>(samples[i].rgb, 1.0) * compute_depth_similarity(samples[i].a, max_z, inv_threshold);
    }
    let rgb = avg.rgb / avg.w;
    return vec4<f32>(rgb, max_z / CONSTANT_FLOAT16F_SCALE);
}

// ---- MainPS ----
fn get_depth_from_ao_input(uv: vec2<f32>) -> f32 {
    if (USE_AO_SETUP_AS_INPUT) {
        return textureSampleLevel(in_setup, point_clamp, uv, 0.0).a * CONSTANT_FLOAT16F_SCALE;
    }
    return calc_scene_depth(uv);
}
fn get_world_space_normal_from_ao_input(uv: vec2<f32>) -> vec3<f32> {
    if (USE_AO_SETUP_AS_INPUT) {
        return textureSampleLevel(in_setup, point_clamp, fract(uv), 0.0).xyz * 2.0 - 1.0;
    }
    return gbuffer_normal(uv);
}

fn compute_upsample_contribution(scene_depth: f32, in_uv: vec2<f32>, center_world_normal: vec3<f32>) -> vec4<f32> {
    let small = 0.0001;
    var weight_sum = small;
    var ret = vec4<f32>(small, 0.0, 0.0, 0.0);
    var min_iteration = 1.0;
    // AO_UPSAMPLE_QUALITY 1 (9 samples) for the AO-setup input passes, 0 (4 samples) at full resolution
    let nine = USE_AO_SETUP_AS_INPUT;
    let count = select(4u, 9u, nine);
    for (var i = 0u; i < count; i = i + 1u) {
        var o: vec2<f32>;
        if (nine) {
            o = vec2<f32>(f32(i % 3u) - 1.0, f32(i / 3u) - 1.0);
        } else {
            // UV[0] (-0.5, 0.5), UV[1] (0.5, 0.5), UV[2] (-0.5, -0.5), UV[3] (0.5, -0.5)
            o = vec2<f32>(select(-0.5, 0.5, (i & 1u) == 1u), select(0.5, -0.5, i >= 2u));
        }
        let uv = in_uv + o * u.in2_size.zw;
        let sample_value = textureSampleLevel(in_lower, point_clamp, uv, 0.0);
        min_iteration = min(min_iteration, sample_value.g);
        let normal_and_depth = textureSampleLevel(in_setup_up, point_clamp, uv, 0.0);
        let sample_depth = normal_and_depth.a * CONSTANT_FLOAT16F_SCALE;
        // when tweaking this constant look for crawling pattern at edges
        var weight = compute_depth_similarity(sample_depth, scene_depth, 0.003);
        let local_world_normal = normal_and_depth.xyz * 2.0 - 1.0;
        weight = weight * clamp(dot(local_world_normal, center_world_normal), 0.0, 1.0);
        ret = ret + vec4<f32>(sample_value.rgb, 1.0) * weight;
        weight_sum = weight_sum + weight;
    }
    ret = ret / weight_sum;
    ret.g = min_iteration;
    return ret;
}

// AO_SAMPLE_QUALITY is 3 in every permutation: blend with the upsampled lower level by MipBlend when there is one
fn compute_lerp_factor() -> f32 {
    if (!USE_UPSAMPLE) { return 0.0; }
    return u.p2.w;
}

fn screen_pos_to_hzb_uv(p: vec2<f32>) -> vec2<f32> { return u.hzb_remap.xy * p + u.hzb_remap.zw; }

fn compute_mip_level(sample_id: u32, step: u32) -> f32 {
    let sample_pos = (f32(sample_id) + 0.5) / f32(sampleset_size());
    let factor = u.p4.z;
    let scale = f32(step + 1u) / f32(sample_steps());
    return log2(factor * scale * sample_pos);
}

// WedgeWithNormal, OPTIMIZATION_O1: float3(InvNormAngleL, InvNormAngleR, Weight = 1)
fn wedge_with_normal(center: vec2<f32>, local_random: vec2<f32>, inv_fov_fix: vec3<f32>, view_pos: vec3<f32>, scaled_normal: vec3<f32>, mip: f32) -> vec2<f32> {
    let pos_l = center + local_random;
    let pos_r = center - local_random;
    let tex_l = textureSampleLevel(hzb_tex, point_clamp, screen_pos_to_hzb_uv(pos_l), mip).r;
    let tex_r = textureSampleLevel(hzb_tex, point_clamp, screen_pos_to_hzb_uv(pos_r), mip).r;
    let abs_l = convert_from_device_z(tex_l);
    let abs_r = convert_from_device_z(tex_r);
    let sample_l = vec3<f32>(pos_l * abs_l, abs_l);
    let sample_r = vec3<f32>(pos_r * abs_r, abs_r);
    let delta_l = (sample_l - view_pos) * inv_fov_fix;
    let delta_r = (sample_r - view_pos) * inv_fov_fix;
    let inv_l = clamp(dot(delta_l, scaled_normal) / dot(delta_l, delta_l), 0.0, 1.0);
    let inv_r = clamp(dot(delta_r, scaled_normal) / dot(delta_r, delta_r), 0.0, 1.0);
    return vec2<f32>(inv_l, inv_r);
}

fn reconstruct_normal(v: vec2<f32>) -> vec3<f32> { return vec3<f32>(v, sqrt(1.0 - dot(v, v))); }

@fragment
fn fs_ao(in: VsOut) -> @location(0) vec4<f32> {
    let power = u.p0.x;
    let ratio = u.p1.w;
    let ao_radius_in_shader = u.p1.z;
    let intensity = u.p0.w;
    let viewport_uv_to_random_uv = u.p1.xy;
    let bias = u.p0.y;
    let scale_factor = u.p2.x;
    let scale_radius_in_ws = u.p2.z;

    // UVAndScreenPos: the input texture UV of this pixel and its screen position (-1..1, y up)
    let uv = in.pos.xy * u.out_size.zw;
    let screen_pos = vec2<f32>(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);

    let inv_tan_half_fov = u.p3.w;
    let fov_fix = vec3<f32>(inv_tan_half_fov, ratio * inv_tan_half_fov, 1.0);
    let inv_fov_fix = 1.0 / fov_fix;

    let scene_depth = get_depth_from_ao_input(uv);
    let world_normal = get_world_space_normal_from_ao_input(uv);
    let view_space_normal = normalize(to_ue_view(world_normal));
    var view_pos = vec3<f32>(screen_pos * scene_depth, scene_depth);
    let actual_radius = ao_radius_in_shader * mix(scene_depth, 1.0, scale_radius_in_ws);
    // add bias after fixup (SSAO_NORMAL_MODE 1)
    view_pos = view_pos + bias * scene_depth * scale_factor * (view_space_normal * fov_fix);

    var weight_acc = vec2<f32>(0.0001);
    // AO_SAMPLE_QUALITY 3: one of 16 base vectors (rotation and scale) from a texture that repeats 4x4, jittered per frame with temporal AA
    let temporal_offset = u.p3.xy;
    let random_vec = (textureSampleLevel(random_tex, point_wrap, temporal_offset + uv * viewport_uv_to_random_uv, 0.0).rg * 2.0 - 1.0) * actual_radius;
    let fov_fix_xy = fov_fix.xy * (1.0 / view_pos.z);
    let random_base = vec4<f32>(random_vec, -random_vec.y, random_vec.x) * vec4<f32>(fov_fix_xy, fov_fix_xy);
    let center = view_pos.xy / view_pos.z;
    // OPTIMIZATION_O1
    let scaled_normal = view_space_normal * (0.08 * mix(scene_depth, 1000.0, scale_radius_in_ws));
    let n_samples = sampleset_size();
    let steps = sample_steps();
    for (var i = 0u; i < n_samples; i = i + 1u) {
        let unrotated = sample_offset(i);
        let local_random = unrotated.x * random_base.xy + unrotated.y * random_base.zw;
        var acc = vec3<f32>(0.0);
        for (var step = 0u; step < steps; step = step + 1u) {
            let scale = f32(step + 1u) / f32(steps);
            let mip = compute_mip_level(i, step);
            let s = wedge_with_normal(center, scale * local_random, inv_fov_fix, view_pos, scaled_normal, mip);
            // combine horizon samples (Weight is 1 with OPTIMIZATION_O1)
            acc = vec3<f32>(max(acc.xy, s), 1.0);
        }
        // Square(): the area scales quadratic with the angle - it gets a bit darker
        weight_acc = weight_acc + vec2<f32>((1.0 - acc.x) * (1.0 - acc.x) * acc.z, acc.z);
        weight_acc = weight_acc + vec2<f32>((1.0 - acc.y) * (1.0 - acc.y) * acc.z, acc.z);
    }

    var ao = weight_acc.x / weight_acc.y;
    if (USE_UPSAMPLE) {
        let filtered = compute_upsample_contribution(scene_depth, uv, world_normal);
        // recombined result from multiple resolutions
        ao = mix(ao, filtered.r, compute_lerp_factor());
    }
    if (!USE_AO_SETUP_AS_INPUT) {
        // full res: soft fade out AO in the distance, then the user AO adjust
        ao = mix(ao, 1.0, clamp(scene_depth * u.p4.x + u.p4.y, 0.0, 1.0));
        ao = 1.0 - (1.0 - pow(abs(ao), power)) * intensity;
    }

    // QUAD_MESSAGE_PASSING_BLUR (SM5): .x AO output, .y SceneDepth, .zw view space normal
    var out_ao = ao;
    if (quad_blur()) {
        let c = vec4<f32>(ao, scene_depth, view_space_normal.xy);
        let dx = dpdxFine(c);
        let dy = dpdyFine(c);
        let m = vec2<f32>(vec2<u32>(in.pos.xy) % vec2<u32>(2u));
        let pix_a = c;
        let pix_b = c - dx * (m.x * 2.0 - 1.0);
        let pix_c = c - dy * (m.y * 2.0 - 1.0);
        var wa = 1.0;
        var wb = 1.0;
        var wc = 1.0;
        // QUAD_MESSAGE_PASSING_NORMAL
        let na = reconstruct_normal(pix_a.zw);
        let nb = reconstruct_normal(pix_b.zw);
        let ncc = reconstruct_normal(pix_c.zw);
        wb = wb * clamp(pow(clamp(dot(na, nb), 0.0, 1.0), 4.0), 0.0, 1.0);
        wc = wc * clamp(pow(clamp(dot(na, ncc), 0.0, 1.0), 4.0), 0.0, 1.0);
        let inv = 1.0 / (wa + wb + wc);
        out_ao = wa * inv * pix_a.x + wb * inv * pix_b.x + wc * inv * pix_c.x;
    }
    if (!USE_AO_SETUP_AS_INPUT || quad_blur()) {
        // full res: "OutColor = OutColor.r" (single channel); with the blur every channel is the blurred value
        return vec4<f32>(out_ao);
    }
    return vec4<f32>(out_ao, 0.0, 0.0, 0.0);
}
diagnostic(off, derivative_uniformity); // TEMPORAL AA: the scene velocity target of UE 4.16 for the
// primitives that move: the skinned models. Static primitives write nothing (cleared to 0 = "no velocity", the TAA shader then uses the camera
// reprojection from depth), exactly like UE where only `DrawsVelocity()` primitives output it. This is the separate velocity pass of VelocityRendering.cpp
// (depth-tested against the scene depth); CookedIniVersion.txt has RendererSettings r.BasePassOutputsVelocity True (L75) but the cooked shader
// set says 0 ([AdditionalSettings] L5899), i.e. the separate pass; the encoded values are the same either way.
// VelocityShader.usf:155-198 / VelocityCommon.usf:9-19: ScreenPos = TranslatedWorldToClip * pos, PrevScreenPos = PrevTranslatedWorldToClip * prev
// pos (previous bones + previous model matrix), Velocity = (ScreenPos.xy / w - jitter) - (PrevScreenPos.xy / w - prev jitter), i.e. the unjittered
// screen positions; EncodeVelocityToTexture (Common.usf:1736-1741) `v * (0.499 * 0.5) + 32767 / 65535`, stored in a PF_G16R16 (16-bit unorm)
// target: the value is quantised to 1/65535 here and kept in an Rg32Float texture.
struct VelU {
    view_proj: mat4x4<f32>,        // jittered (rasterisation, must match the scene pass depth)
    view_proj_no_aa: mat4x4<f32>,  // this frame, no jitter
    prev_view_proj_no_aa: mat4x4<f32>,
}
struct Object { model: mat4x4<f32> }
@group(0) @binding(0) var<uniform> vu: VelU;
@group(1) @binding(0) var<uniform> object: Object;
@group(1) @binding(1) var<storage, read> bones: array<mat4x4<f32>>;
@group(2) @binding(0) var<uniform> prev_object: Object;
@group(2) @binding(1) var<storage, read> prev_bones: array<mat4x4<f32>>;

struct VsOut {
    @builtin(position) clip: vec4<f32>,
    @location(0) cur: vec4<f32>,
    @location(1) prev: vec4<f32>,
}

fn skin_velocity(pos: vec3<f32>, joints: vec4<u32>, weights: vec4<f32>) -> VsOut {
    var o: VsOut;
    // same expression as scene.wgsl vs_skinned (the depth test against the scene depth needs the same position)
    let m = bones[joints.x] * weights.x + bones[joints.y] * weights.y + bones[joints.z] * weights.z + bones[joints.w] * weights.w;
    let p_local = (m * vec4<f32>(pos, 1.0)).xyz;
    let wp = object.model * vec4<f32>(p_local, 1.0);
    o.clip = vu.view_proj * wp;
    o.cur = vu.view_proj_no_aa * wp;
    let pm = prev_bones[joints.x] * weights.x + prev_bones[joints.y] * weights.y + prev_bones[joints.z] * weights.z + prev_bones[joints.w] * weights.w;
    let pp = prev_object.model * vec4<f32>((pm * vec4<f32>(pos, 1.0)).xyz, 1.0);
    o.prev = vu.prev_view_proj_no_aa * pp;
    return o;
}

@vertex
fn vs_skinned(@location(0) pos: vec3<f32>, @location(1) normal: vec3<f32>, @location(2) uv: vec2<f32>, @location(3) joints: vec4<u32>, @location(4) weights: vec4<f32>) -> VsOut {
    return skin_velocity(pos, joints, weights);
}

// VELOCITY (2026-10-07): the BR character parts (char_scene.wgsl). Their pre-pass runs the material's FDepthOnlyPS coverage clip with an `@invariant` position
// (CHAR PREPASS), so this twin is `@invariant` too and depth-tested EQUAL against the scene depth: it writes exactly the pixels the clipped pre-pass kept
// (UE: the velocity pass of a masked material runs its clip, VelocityShader.usf:248 `GetMaterialClippingVelocity`). Was: the plain `vs_skinned` + LessEqual with a
// -2 depth bias, which wrote the clipped-away texels (velocity on the background next to the hair / cloth edges) and lost covered ones whose depth
// rounded differently (holes), so those pixels reprojected with the camera only: the lagging outline around the moving character.
struct VsOutChar {
    @builtin(position) @invariant clip: vec4<f32>,
    @location(0) cur: vec4<f32>,
    @location(1) prev: vec4<f32>,
}
@vertex
fn vs_skinned_char(@location(0) pos: vec3<f32>, @location(1) normal: vec3<f32>, @location(2) uv: vec2<f32>, @location(3) joints: vec4<u32>, @location(4) weights: vec4<f32>) -> VsOutChar {
    let s = skin_velocity(pos, joints, weights);
    var o: VsOutChar;
    o.clip = s.clip; o.cur = s.cur; o.prev = s.prev;
    return o;
}
@fragment
fn fs_velocity_char(in: VsOutChar) -> @location(0) vec4<f32> { return velocity_out(in.cur, in.prev); }

@fragment
fn fs_velocity(in: VsOut) -> @location(0) vec4<f32> { return velocity_out(in.cur, in.prev); }
fn velocity_out(cur: vec4<f32>, prev: vec4<f32>) -> vec4<f32> {
    let v = cur.xy / cur.w - prev.xy / prev.w;
    let enc = v * (0.499 * 0.5) + 32767.0 / 65535.0;
    // PF_G16R16 unorm storage
    let q = round(clamp(enc, vec2<f32>(0.0), vec2<f32>(1.0)) * 65535.0) / 65535.0;
    return vec4<f32>(q, 0.0, 0.0);
}
diagnostic(off, derivative_uniformity); // TEMPORAL AA: port of UE 4.16 `MainTemporalAAPS` / `MainFastTemporalAAPS` (PostProcessTemporalAA.usf:345-480) = PostProcessTemporalCommon.usf
// with the Main defines: AA_FILTERED 1, AA_BORDER 1, AA_CROSS 2, AA_YCOCG 1, AA_BICUBIC 1, AA_TONE 1, AA_CLAMP 1, AA_NAN 1, AA_DYNAMIC 1,
// AA_FILTERED_CONTRAST_LIMIT 1, AA_ALPHA = POST_PROCESS_ALPHA = 0, AA_LERP 0; `Main` adds AA_DYNAMIC_ANTIGHOST 1 (Epic, r.PostProcessAAQuality 4),
// `MainFast` does not (High, quality 3). AA_AABB / AA_ROUND only affect the non-YCoCg path and are unused.
// Inputs (PostProcessTemporalAA.cpp:120-125 FilterTable): Input0 scene colour (point), Input1 history (bilinear, clamp), Input3 velocity (point),
// SceneDepthTexture (point). Everything is the same pixel grid (no screen-percentage history rescale: history and view have the same size).
// Port differences: this renderer's depth is 0 = near / 1 = far, so the "nearest depth" of the AA_CROSS search is the MINIMUM (UE: inverted Z, max);
// output 1 additionally writes the resolved colour back to the scene colour with the CURRENT frame's alpha (the ambient share post.wgsl uses
// for its AO), UE's TAA output alpha stays in the history (output 0).
struct TaaU {
    plus0: vec4<f32>,          // PlusWeights[0..3]
    plus1: vec4<f32>,          // PlusWeights[4], CurrentFrameWeight, VelocityScaling, flags (1 = AA_DYNAMIC_ANTIGHOST, 2 = responsive everywhere: no history / camera cut)
    clip_to_prev: mat4x4<f32>, // View.ClipToPrevClip (no-AA matrices), column vectors: PrevClip = M * ThisClip
    viewport: vec4<f32>,       // w, h, 1/w, 1/h (ViewportSize = PostprocessInput0Size = PostprocessInput1Size)
}
struct ExposureState { ev: f32, target_ev: f32, exposure: f32, avg_luminance: f32 }
@group(0) @binding(0) var<uniform> tu: TaaU;
@group(0) @binding(1) var scene_in: texture_2d<f32>;
@group(0) @binding(2) var history: texture_2d<f32>;
@group(0) @binding(3) var lin_samp: sampler;
@group(0) @binding(4) var depth_tex: texture_depth_2d;
@group(0) @binding(5) var velocity_tex: texture_2d<f32>;
@group(0) @binding(6) var<storage, read> exposure_state: ExposureState;
// STORM TAA: responsive-AA mask (UE stencil bit STENCIL_TEMPORAL_RESPONSIVE_AA_MASK): 0 = a bEnableResponsiveAA translucent draw covered the pixel (taa.rs)
@group(0) @binding(7) var responsive_mask: texture_2d<f32>;

struct VsOut { @builtin(position) clip: vec4<f32> }
@vertex
fn vs_main(@builtin(vertex_index) i: u32) -> VsOut {
    var o: VsOut;
    let x = f32(i32(i & 1u) * 4 - 1);
    let y = f32(i32((i >> 1u) & 1u) * 4 - 1);
    o.clip = vec4<f32>(x, y, 0.0, 1.0);
    return o;
}

fn clampi(p: vec2<i32>) -> vec2<i32> { return clamp(p, vec2<i32>(0), vec2<i32>(tu.viewport.xy) - vec2<i32>(1)); }
fn color_at(p: vec2<i32>) -> vec4<f32> { return textureLoad(scene_in, clampi(p), 0); }
fn depth_at(p: vec2<i32>) -> f32 { return textureLoad(depth_tex, clampi(p), 0); }
fn velocity_at(p: vec2<i32>) -> vec2<f32> { return textureLoad(velocity_tex, clampi(p), 0).xy; }

fn rgb_to_ycocg(c: vec3<f32>) -> vec3<f32> {
    return vec3<f32>(dot(c, vec3<f32>(1.0, 2.0, 1.0)), dot(c, vec3<f32>(2.0, 0.0, -2.0)), dot(c, vec3<f32>(-1.0, 2.0, -1.0)));
}
fn ycocg_to_rgb(c: vec3<f32>) -> vec3<f32> {
    let y = c.x * 0.25; let co = c.y * 0.25; let cg = c.z * 0.25;
    return vec3<f32>(y + co - cg, y + cg, y - co - cg);
}
fn hdr_weight_y(y: f32, e: f32) -> f32 { return 1.0 / (y * e + 1.0); }
fn hdr_weight_inv_y(y: f32, e: f32) -> f32 { return 1.0 / (y * -e + 1.0); }
// DecodeVelocityFromTexture (Common.usf:1743-1750)
fn decode_velocity(v: vec2<f32>) -> vec2<f32> { let inv = 1.0 / (0.499 * 0.5); return v * inv - 32767.0 / 65535.0 * inv; }

// Texture2DSampleBicubic (Common.usf:405-471): Catmull-Rom in five bilinear taps, corners dropped and the weights renormalised
fn sample_bicubic(uv_in: vec2<f32>, size: vec2<f32>) -> vec4<f32> {
    let inv = 1.0 / size;
    let uv = uv_in * size;
    let tc = floor(uv - 0.5) + 0.5;
    let f = uv - tc;
    let f2 = f * f;
    let f3 = f2 * f;
    let w0 = f2 - 0.5 * (f3 + f);
    let w1 = 1.5 * f3 - 2.5 * f2 + 1.0;
    let w3 = 0.5 * (f3 - f2);
    let w2 = 1.0 - w0 - w1 - w3;
    let wt0 = w0; let wt1 = w1 + w2; let wt2 = w3;
    let s0 = (tc - 1.0) * inv;
    let s1 = (tc + w2 / wt1) * inv;
    let s2 = (tc + 2.0) * inv;
    var c = textureSampleLevel(history, lin_samp, vec2<f32>(s1.x, s0.y), 0.0) * wt1.x * wt0.y;
    c = c + textureSampleLevel(history, lin_samp, vec2<f32>(s0.x, s1.y), 0.0) * wt0.x * wt1.y;
    c = c + textureSampleLevel(history, lin_samp, vec2<f32>(s1.x, s1.y), 0.0) * wt1.x * wt1.y;
    c = c + textureSampleLevel(history, lin_samp, vec2<f32>(s2.x, s1.y), 0.0) * wt2.x * wt1.y;
    c = c + textureSampleLevel(history, lin_samp, vec2<f32>(s1.x, s2.y), 0.0) * wt1.x * wt2.y;
    let corner = wt1.x * wt0.y + wt0.x * wt1.y + wt1.x * wt1.y + wt2.x * wt1.y + wt1.x * wt2.y;
    return c / corner;
}

struct FsOut { @location(0) history: vec4<f32>, @location(1) scene: vec4<f32> }

@fragment
fn fs_main(in: VsOut) -> FsOut {
    let px = vec2<i32>(floor(in.clip.xy));
    let uv = in.clip.xy * tu.viewport.zw;
    // ScreenPos = (UV * Size - 0.5 - ScreenPosToPixel.zw) / ScreenPosToPixel.xy (RenderingCompositionGraph.cpp:902-907): x right, y up
    let screen_pos = vec2<f32>(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
    let flags = u32(tu.plus1.w);
    let antighost = (flags & 1u) != 0u;
    let responsive = (flags & 2u) != 0u;
    let exposure = exposure_state.exposure;   // InExposureScale = the eye adaptation of the previous frame (FPostProcessTonemapVS)
    let current_frame_weight = tu.plus1.y;

    // FIND MOTION OF PIXEL AND NEAREST IN NEIGHBORHOOD (AA_CROSS 2)
    var pos_z = depth_at(px);
    var velocity_offset = vec2<i32>(0);
    let d = vec4<f32>(depth_at(px + vec2<i32>(-2, -2)), depth_at(px + vec2<i32>(2, -2)), depth_at(px + vec2<i32>(-2, 2)), depth_at(px + vec2<i32>(2, 2)));
    var depth_offset = vec2<i32>(2, 2);
    var depth_offset_xx = 2;
    if (d.x < d.y) { depth_offset_xx = -2; }
    if (d.z < d.w) { depth_offset.x = -2; }
    let d_xy = min(d.x, d.y);
    let d_zw = min(d.z, d.w);
    if (d_xy < d_zw) { depth_offset.y = -2; depth_offset.x = depth_offset_xx; }
    let d_xyzw = min(d_xy, d_zw);
    if (d_xyzw < pos_z) { velocity_offset = depth_offset; pos_z = d_xyzw; }

    // camera motion for the pixel (or the nearest pixel)
    let this_clip = vec4<f32>(screen_pos, pos_z, 1.0);
    let prev_clip = tu.clip_to_prev * this_clip;
    let prev_screen = prev_clip.xy / prev_clip.w;
    var back_n = screen_pos - prev_screen;
    // AA_DYNAMIC
    let velocity_n = velocity_at(px + velocity_offset) * tu.plus1.z;
    if (velocity_n.x > 0.0) { back_n = decode_velocity(velocity_n); }
    back_n = screen_pos - back_n;
    let off_screen = max(abs(back_n.x), abs(back_n.y)) >= 1.0;
    back_n.x = clamp(back_n.x, -1.0 + tu.viewport.z, 1.0 - tu.viewport.z);
    back_n.y = clamp(back_n.y, -1.0 + tu.viewport.w, 1.0 - tu.viewport.w);
    let history_uv = vec2<f32>(back_n.x * 0.5 + 0.5, 0.5 - back_n.y * 0.5);

    // FILTER PIXEL AND GET NEIGHBORHOOD (YCoCg, 5 taps)
    let center = color_at(px);
    var n1 = rgb_to_ycocg(color_at(px + vec2<i32>(0, -1)).rgb);
    var n3 = rgb_to_ycocg(color_at(px + vec2<i32>(-1, 0)).rgb);
    var n4 = rgb_to_ycocg(center.rgb);
    var n5 = rgb_to_ycocg(color_at(px + vec2<i32>(1, 0)).rgb);
    var n7 = rgb_to_ycocg(color_at(px + vec2<i32>(0, 1)).rgb);
    // AA_FILTERED_CONTRAST_LIMIT && AA_TONE
    let luma_m1 = n1.x + n3.x + n4.x + n5.x + n7.x;
    let luma_m2 = n1.x * n1.x + n3.x * n3.x + n4.x * n4.x + n5.x * n5.x + n7.x * n7.x;
    let luma_avg = luma_m1 * (1.0 / 5.0);
    let luma_var = abs(luma_m2 * (1.0 / 5.0) - luma_avg * luma_avg);
    // AA_TONE
    n1 = n1 * hdr_weight_y(n1.x, exposure);
    n3 = n3 * hdr_weight_y(n3.x, exposure);
    n4 = n4 * hdr_weight_y(n4.x, exposure);
    n5 = n5 * hdr_weight_y(n5.x, exposure);
    n7 = n7 * hdr_weight_y(n7.x, exposure);
    var filtered = n1 * tu.plus0.x + n3 * tu.plus0.y + n4 * tu.plus0.z + n5 * tu.plus0.w + n7 * tu.plus1.x;
    if (luma_var > 1.0) { filtered = n4; }
    // AA_BORDER: unfiltered for the 1 pixel border
    let test_pos = abs(screen_pos) + tu.viewport.zw * 2.0;
    if (max(test_pos.x, test_pos.y) >= 1.0) { filtered = n4; }
    let neighbor_min = min(min(min(n1, n3), min(n4, n5)), n7);
    let neighbor_max = max(max(max(n1, n3), max(n4, n5)), n7);

    // FETCH HISTORY (AA_BICUBIC); no history (first frame / camera cut) = BlackDummy
    var history_color = vec4<f32>(0.0);
    if (!responsive) { history_color = sample_bicubic(history_uv, tu.viewport.xy); }
    var hist = rgb_to_ycocg(history_color.rgb);
    hist = hist * hdr_weight_y(hist.x, exposure);
    var hist_a = history_color.a;

    // AA_DYNAMIC_ANTIGHOST (Main only)
    let dyn4 = velocity_at(px).x > 0.0;
    if (antighost) {
        let dynamic = velocity_at(px + vec2<i32>(0, -1)).x > 0.0 || velocity_at(px + vec2<i32>(-1, 0)).x > 0.0 || dyn4
            || velocity_at(px + vec2<i32>(1, 0)).x > 0.0 || velocity_at(px + vec2<i32>(0, 1)).x > 0.0;
        if (!dynamic && hist_a > 0.0) { hist = filtered; hist_a = 0.0; }
    }

    // AA_CLAMP (YCoCg: plain clamp)
    hist = clamp(hist, neighbor_min, neighbor_max);

    // COMPUTE BLEND AMOUNT: AA_TONE -> CurrentFrameWeight; responsive -> 1/4
    var blend_final = current_frame_weight;
    if (responsive) { blend_final = 1.0 / 4.0; }
    // STORM TAA: bIsResponsiveAAPixel of a tagged pixel (PostProcessTemporalCommon.usf:114-123 RESPONSIVE pass / :565): 1/4 of the new frame, the history
    // still fetched, clamped and anti-ghosted above (only the no-history flag 2 drops it)
    if (textureLoad(responsive_mask, clampi(px), 0).r < 0.5) { blend_final = 1.0 / 4.0; }
    if (off_screen) { hist = filtered; hist_a = 0.0; }

    var out_rgb = mix(hist, filtered, blend_final);
    var out_a = 0.0;
    if (responsive) { out_a = max(hist_a, 1.0 / 2.0); }
    out_rgb = out_rgb * hdr_weight_inv_y(out_rgb.x, exposure);
    out_rgb = ycocg_to_rgb(out_rgb);
    // AA_NAN: NaN and negative colours to black
    out_rgb = select(vec3<f32>(0.0), out_rgb, out_rgb > vec3<f32>(0.0));
    // AA_DYNAMIC_ANTIGHOST: alpha = Dynamic4, otherwise !AA_ALPHA: 0
    if (antighost) { out_a = select(0.0, 1.0, dyn4); } else { out_a = 0.0; }

    var o: FsOut;
    o.history = vec4<f32>(out_rgb, out_a);
    o.scene = vec4<f32>(out_rgb, center.a);
    // VELOCITY DEBUG (verification aid, taa.rs FN_TAA_DEBUG): the velocity buffer of this pixel instead of the resolve
    if ((flags & 4u) != 0u) {
        let raw = velocity_at(px);
        var own = 0.0;
        if (raw.x > 0.0) { own = length(decode_velocity(raw) * 0.5 * tu.viewport.xy); }
        let cam_px = length((screen_pos - prev_screen) * 0.5 * tu.viewport.xy);
        o.scene = vec4<f32>(select(0.0, 1.0, raw.x > 0.0), own / 10.0, cam_px / 10.0, center.a);
        if ((flags & 8u) != 0u) { o.scene = vec4<f32>(select(0.0, 1.0, own > 0.5), select(0.0, 1.0, own > 2.0), select(0.0, 1.0, own > 8.0), center.a); }
    }
    return o;
}
