fn cone_cone_intersection(arc0: f32, arc1: f32, angle_between: f32) -> f32 {
    let diff = abs(arc0 - arc1);
    return smoothstep(0.0, 1.0, 1.0 - clamp((angle_between - diff) / (arc0 + arc1 - diff), 0.0, 1.0));
